static const ChangeLine CL_42[] = {
    { "Your songs no longer vanish when a Trust bard sings over them. All marches share one status id, so a Trust's cast used to steal the attribution and the buff-source filter then hid YOUR own song while it was plainly still up.",
      "Vos chants ne disparaissent plus quand un trust barde chante par-dessus. Toutes les marches partagent un identifiant de statut, donc l'incantation d'un trust volait l'attribution et le filtre de source masquait VOTRE propre chant alors qu'il tournait toujours.", CK_FIXED, "Timers", "Timers" },
    { "A buff someone else put on you now shows WHO cast it, and Trust songs show their real name and tier instead of borrowing yours. Rolls name their caster too.",
      "Un buff pos\xC3\xA9 par quelqu'un d'autre indique d\xC3\xA9sormais QUI l'a lanc\xC3\xA9, et les chants des trusts portent leur vrai nom et leur palier au lieu d'emprunter les v\xC3\xB4tres. Les rolls nomment aussi leur lanceur.", CK_NEW, "Timers", "Timers" },
    { "The Duration column is ordered your own casts first, then real party players, then Trusts -- each block still sorted soonest-to-expire.",
      "La colonne Dur\xC3\xA9""e est class\xC3\xA9""e vos propres lancers d'abord, puis les vrais joueurs de l'\xC3\xA9quipe, puis les trusts -- chaque bloc restant tri\xC3\xA9 par expiration la plus proche.", CK_IMPROVED, "Timers", "Timers" },
    { "Song tiers, modifier tags and casters now survive //unload + //load, even after several minutes. The cache is written on unload and no longer discarded after two minutes.",
      "Les paliers de chants, les marqueurs et les lanceurs survivent d\xC3\xA9sormais \xC3\xA0 //unload + //load, m\xC3\xAAme apr\xC3\xA8s plusieurs minutes. Le cache est \xC3\xA9""crit au d\xC3\xA9""chargement et n'est plus jet\xC3\xA9 au bout de deux minutes.", CK_FIXED, "Timers", "Timers" },
    { "Status icons could be missing for a whole session on a machine left running more than 24 days -- the retry that reloads the icon atlas never armed.",
      "Les ic\xC3\xB4nes de statut pouvaient manquer toute une session sur une machine allum\xC3\xA9""e depuis plus de 24 jours -- la relance qui recharge l'atlas ne s'armait jamais.", CK_FIXED, "HUD", "HUD" },
    { "Dragging the Timers row-spacing slider rewrote the whole config file every frame, making it stutter.",
      "Faire glisser le curseur d'espacement des lignes de Timers r\xC3\xA9\xC3\xA9""crivait tout le fichier de config \xC3\xA0 chaque image, ce qui le rendait saccad\xC3\xA9.", CK_FIXED, "Config", "Config" },
    { "One field of the action packet was read on 10 bits instead of 6 (confirmed against the game's own parser), which could inflate the target count of an area spell.",
      "Un champ du paquet d'action \xC3\xA9tait lu sur 10 bits au lieu de 6 (confirm\xC3\xA9 face \xC3\xA0 l'analyseur du jeu), ce qui pouvait gonfler le nombre de cibles d'un sort de zone.", CK_FIXED, "HUD", "HUD" },
    { "Alliance members now have their own colour instead of sharing the party one -- read from the client's own party/alliance flags on the entity.",
      "Les membres d'alliance ont d\xC3\xA9sormais leur propre couleur au lieu de partager celle de l'\xC3\xA9quipe -- lue directement sur les drapeaux party/alliance du client.", CK_NEW, "Minimap", "Minicarte" },
};

static const ChangeLine CL_43[] = {
    { "Buff countdowns now match the game's own display to the second. They were running 2-3 s low: we derived the current time from the Windows clock, while the client keeps its own counter re-synced from the server on every zone -- so any drift between your PC and the server landed on every timer.",
      "Les d\xC3\xA9""comptes de buffs correspondent d\xC3\xA9sormais \xC3\xA0 la seconde pr\xC3\xA8s \xC3\xA0 ceux du jeu. Ils accusaient 2 \xC3\xA0 3 s de retard : nous calculions l'heure courante depuis l'horloge Windows, alors que le client tient son propre compteur resynchronis\xC3\xA9 sur le serveur \xC3\xA0 chaque zonage -- toute d\xC3\xA9rive entre ton PC et le serveur atterrissait donc sur chaque minuteur.", CK_FIXED, "Timers", "Timers" },
    { "Same fix, second cause : remaining time was rounded down where the game rounds up, costing one further second on almost every row.",
      "M\xC3\xAAme correctif, seconde cause : le temps restant \xC3\xA9tait arrondi \xC3\xA0 l'inf\xC3\xA9rieur l\xC3\xA0 o\xC3\xB9 le jeu arrondit au sup\xC3\xA9rieur, ce qui co\xC3\xBBtait une seconde de plus sur presque chaque ligne.", CK_FIXED, "Timers", "Timers" },
    { "Aftermath is now attributed to you rather than left without an owner -- it can only ever come from your own weaponskill, and the game announces no cast for it.",
      "Aftermath t'est d\xC3\xA9sormais attribu\xC3\xA9 au lieu de rester sans propri\xC3\xA9taire -- il ne peut venir que de ton propre weaponskill, et le jeu n'en annonce aucune incantation.", CK_FIXED, "Timers", "Timers" },
};

static const ChangeLine CL_44[] = {
    { "A song another player casts on you now shows the job abilities that were up when they cast it -- Nightingale, Troubadour, Soul Voice, Marcato -- and a Corsair's roll shows Crooked Cards. Read from the party-buff cache, so it works for party members (not alliance).",
      "Un chant qu'un autre joueur vous pose affiche d\xC3\xA9sormais les aptitudes qui \xC3\xA9taient actives quand il l'a lanc\xC3\xA9 -- Nightingale, Troubadour, Soul Voice, Marcato -- et un roll de Corsair affiche Crooked Cards. Lu depuis le cache de buffs du groupe, donc valable pour les membres de votre \xC3\xA9quipe (pas l'alliance).", CK_NEW, "Timers", "Timers" },
    { "Ability tags are amber like your own, the caster's name is grey beside them -- what was active and who cast it are two different things to read.",
      "Les marqueurs d'aptitudes sont en ambre comme les v\xC3\xB4tres, le nom du lanceur en gris \xC3\xA0 c\xC3\xB4t\xC3\xA9 -- ce qui \xC3\xA9tait actif et qui l'a lanc\xC3\xA9 sont deux informations diff\xC3\xA9rentes \xC3\xA0 lire.", CK_IMPROVED, "Timers", "Timers" },
    { "Another player's songs showed only a generic status name, with no tier and no tags. A safety check meant to stop a trust claiming your long song was rejecting real players' songs too, since we predicted their duration without knowing their Troubadour. It now applies to trusts only, and a party member's song duration accounts for the abilities they had up.",
      "Les chants d'un autre joueur n'affichaient qu'un nom de statut g\xC3\xA9n\xC3\xA9rique, sans palier ni marqueur. Un contr\xC3\xB4le de s\xC3\xA9""curit\xC3\xA9 cens\xC3\xA9 emp\xC3\xAA""cher un trust de revendiquer votre long chant rejetait aussi les chants des vrais joueurs, car nous pr\xC3\xA9""disions leur dur\xC3\xA9""e sans conna\xC3\xAEtre leur Troubadour. Il ne s'applique plus qu'aux trusts, et la dur\xC3\xA9""e d'un chant d'un membre du groupe tient compte des aptitudes qu'il avait actives.", CK_FIXED, "Timers", "Timers" },
};

static const ChangeLine CL_45[] = {
    { "The HP bar is now a flowing liquid vial tinted by the target's allegiance -- a boiling blood-red for a monster, its own vivid hue for a player or NPC, every colour at one consistent intensity. The whole box (HP, sub-target, distance) shares the same recessed glass frame.",
      "La barre HP est d\xC3\xA9sormais une fiole de liquide en mouvement, teint\xC3\xA9""e selon l'all\xC3\xA9geance de la cible -- un rouge sang bouillonnant pour un monstre, sa propre teinte vive pour un joueur ou un PNJ, toutes \xC3\xA0 la m\xC3\xAAme intensit\xC3\xA9. Toute la bo\xC3\xAEte (HP, sous-cible, distance) partage le m\xC3\xAAme cadre en verre.", CK_IMPROVED, "Target", "Cible" },
    { "Scholar stratagems now show \"Stratagem\" with the number of charges available and the time to the next one, instead of always showing \"Penury\" (they all share one recast).",
      "Les stratag\xC3\xA8mes de Scholar affichent d\xC3\xA9sormais \"Stratagem\" avec le nombre de charges disponibles et le temps avant la prochaine, au lieu d'afficher toujours \"Penury\" (ils partagent tous un seul recast).", CK_FIXED, "Timers", "Timers" },
    { "A song's SV / NT / TR / M tags no longer vanish a few minutes in on a long (Troubadour'd) song -- the tag now lasts as long as the song itself.",
      "Les marqueurs SV / NT / TR / M d'un chant ne disparaissent plus au bout de quelques minutes sur un chant long (sous Troubadour) -- le marqueur tient d\xC3\xA9sormais aussi longtemps que le chant.", CK_FIXED, "Timers", "Timers" },
    { "A dead member stays in place with all their info and HP 0, shown in a pulsing red instead of being greyed out as if in another zone. Death and out-of-zone are now told apart by the member's actual zone, not by missing HP.",
      "Un membre mort reste \xC3\xA0 sa place avec toutes ses infos et HP 0, affich\xC3\xA9 en rouge pulsant au lieu d'\xC3\xAAtre gris\xC3\xA9 comme s'il \xC3\xA9tait dans une autre zone. Mort et hors-zone sont d\xC3\xA9sormais distingu\xC3\xA9s par la vraie zone du membre, pas par l'absence de HP.", CK_FIXED, "Party", "Groupe" },
    { "Damage job abilities (Jump, High Jump, Weapon Bash, Shield Bash...) no longer trigger the weaponskill popup as if they were a WS -- they share an id with real weaponskills, so they are now told apart by the action message.",
      "Les aptitudes de d\xC3\xA9g\xC3\xA2ts (Jump, High Jump, Weapon Bash, Shield Bash...) ne d\xC3\xA9""clenchent plus le popup de weaponskill comme si c'en \xC3\xA9tait un -- elles partagent un identifiant avec de vrais WS, elles sont donc d\xC3\xA9sormais distingu\xC3\xA9""es par le message d'action.", CK_FIXED, "Skillchains", "Skillchains" },
};

static const ChangeLine CL_46[] = {
    { "Equipment viewer : a gear icon that failed to decode from the game's ROM on the FIRST touch -- which happens on a Program Files install when antivirus or Controlled Folder Access briefly blocks the file -- no longer sticks as a raw item id for the whole session. The failed slots are now retried for ~15 seconds before giving up, and the give-up is logged.",
      "Visualiseur d'\xC3\xA9quipement : une ic\xC3\xB4ne qui n'a pas pu \xC3\xAAtre d\xC3\xA9""cod\xC3\xA9""e depuis la ROM du jeu au PREMIER acc\xC3\xA8s -- ce qui arrive sur une installation en Program Files quand l'antivirus ou Controlled Folder Access bloque bri\xC3\xA8vement le fichier -- ne reste plus bloqu\xC3\xA9""e en identifiant brut pour toute la session. Les emplacements en \xC3\xA9""chec sont d\xC3\xA9sormais r\xC3\xA9""essay\xC3\xA9s pendant ~15 secondes avant d'abandonner, et l'abandon est journalis\xC3\xA9.", CK_FIXED, "Player", "Joueur" },
};

static const ChangeLine CL_47[] = {
    { "Hardening pass across every module : a texture or icon that failed to load on a bad-timed frame (device not ready at zone-in, an asset briefly held by the updater or antivirus) no longer stays missing for the whole session. The buff-icon atlas, party / player / target / grimoire / zone-tracker / treasure icons, and the FFXI window skin all retry now.",
      "Passe de durcissement sur tous les modules : une texture ou une ic\xC3\xB4ne qui n'a pas pu se charger sur une image mal synchronis\xC3\xA9""e (p\xC3\xA9riph\xC3\xA9rique pas pr\xC3\xAAt au changement de zone, un fichier bri\xC3\xA8vement tenu par la mise \xC3\xA0 jour ou l'antivirus) ne reste plus absente toute la session. L'atlas d'ic\xC3\xB4nes de buffs, les ic\xC3\xB4nes party / player / cible / grimoire / suivi de zone / tr\xC3\xA9sor, et le skin de fen\xC3\xAAtre FFXI r\xC3\xA9""essaient d\xC3\xA9sormais.", CK_FIXED, "HUD", "HUD" },
    { "The moon on the minimap clock could stay a blank hole for up to an hour if its image failed to build on a bad frame.",
      "La lune de l'horloge du minimap pouvait rester un trou vide jusqu'\xC3\xA0 une heure si son image \xC3\xA9""chouait \xC3\xA0 se construire sur une mauvaise image.", CK_FIXED, "Minimap", "Minicarte" },
    { "Your Corsair roll pips, bard song tags and buff casters could all be lost for the session if the cache file was momentarily locked at //unload+//load. It retries now.",
      "Les pips de rolls Corsair, les marqueurs de chants barde et les lanceurs de buffs pouvaient tous \xC3\xAAtre perdus pour la session si le fichier cache \xC3\xA9tait momentan\xC3\xA9ment verrouill\xC3\xA9 au //unload+//load. Il r\xC3\xA9""essaie d\xC3\xA9sormais.", CK_FIXED, "Timers", "Timers" },
    { "A false red buff \"OUT\" alert could flash forever for an alliance member (or a party member out of zone), whose buffs the game simply does not report to us -- \"no data\" was read as \"buff gone\".",
      "Une fausse alerte rouge de buff \"OUT\" pouvait clignoter ind\xC3\xA9""finiment pour un membre d'alliance (ou un membre de party hors zone), dont le jeu ne nous transmet simplement pas les buffs -- \"pas de donn\xC3\xA9""es\" \xC3\xA9tait lu comme \"buff parti\".", CK_FIXED, "Timers", "Timers" },
    { "The Hate list could silently lose rows on multi-target actions (the target list was read with a fixed stride that breaks when an earlier target crits or procs).",
      "La liste de haine pouvait perdre des lignes en silence sur les actions multi-cibles (la liste des cibles \xC3\xA9tait lue avec un pas fixe qui casse d\xC3\xA8s qu'une cible pr\xC3\xA9""c\xC3\xA9""dente fait un critique ou un proc).", CK_FIXED, "Hate List", "Liste de haine" },
    { "New command : //aio selfcheck writes the health of every texture/icon load to aiohud_debug.log (used to verify the fixes above).",
      "Nouvelle commande : //aio selfcheck \xC3\xA9""crit la sant\xC3\xA9 de chaque chargement de texture/ic\xC3\xB4ne dans aiohud_debug.log (sert \xC3\xA0 v\xC3\xA9rifier les corrections ci-dessus).", CK_NEW, "HUD", "HUD" },
};

static const ChangeLine CL_48[] = {
    { "The Treasure Pool box could appear with no pool in the game for about a minute. The pool is now checked against the game's own treasure window every frame, so a leftover item can no longer linger.",
      "La bo\xC3\xAEte Treasure Pool pouvait s'afficher sans pool dans le jeu pendant environ une minute. Le pool est d\xC3\xA9sormais compar\xC3\xA9 \xC3\xA0 la fen\xC3\xAAtre tr\xC3\xA9sor du jeu \xC3\xA0 chaque image, donc un objet r\xC3\xA9siduel ne peut plus tra\xC3\xAEner.", CK_FIXED, "Treasure Pool", "Tr\xC3\xA9sor" },
    { "The config scrollbars could not be grabbed -- only the mouse wheel scrolled. You can now drag the scrollbar to move through the options, Help, Update and Debug tabs.",
      "Les barres de d\xC3\xA9""filement de la config ne pouvaient pas \xC3\xAAtre attrap\xC3\xA9""es -- seule la molette faisait d\xC3\xA9""filer. On peut d\xC3\xA9sormais glisser la barre pour parcourir les onglets options, Aide, Mise \xC3\xA0 jour et Debug.", CK_FIXED, "Config", "Config" },
    { "When boxes overlap, only the top one now reacts to the mouse, and the top toolbar always keeps priority -- a box parked underneath no longer steals its clicks.",
      "Quand des bo\xC3\xAEtes se chevauchent, seule celle du dessus r\xC3\xA9""agit \xC3\xA0 la souris, et la barre du haut garde toujours la priorit\xC3\xA9 -- une bo\xC3\xAEte gar\xC3\xA9""e dessous ne vole plus ses clics.", CK_FIXED, "Edit Layout", "\xC3\x89""diter dispo" },
    { "A Debug tab in the config (next to Update) lists the known bugs and the planned work, kept up to date.",
      "Un onglet Debug dans la config (\xC3\xA0 c\xC3\xB4t\xC3\xA9 de Mise \xC3\xA0 jour) liste les bugs connus et le travail pr\xC3\xA9vu, tenu \xC3\xA0 jour.", CK_NEW, "Config", "Config" },
};

static const ChangeLine CL_79[] = {
    { "*The HUD comes back after Windower's August 16 update.* Windower updates itself, and that one moved the place where the plugin reads everything about your character. Every box vanished at once -- while the config window still opened and simply said you were not logged in, which is exactly what it saw. Nothing was broken in the plugin : it was reading an address that no longer meant anything.",
      "*Le HUD revient apr\xC3\xA8s la mise \xC3\xA0 jour Windower du 16 ao\xC3\xBBt.* Windower se met \xC3\xA0 jour tout seul, et celle-ci a d\xC3\xA9plac\xC3\xA9 l'endroit o\xC3\xB9 le plugin lit tout ce qui concerne votre personnage. Toutes les bo\xC3\xAEtes ont disparu d'un coup -- pendant que la fen\xC3\xAAtre de config s'ouvrait encore et disait simplement que vous n'\xC3\xA9tiez pas connect\xC3\xA9, ce qui est exactement ce qu'elle voyait. Rien n'\xC3\xA9tait cass\xC3\xA9 dans le plugin : il lisait une adresse qui ne voulait plus rien dire.", CK_FIXED, "HUD", "HUD" },
    { "*And it now finds that address by itself, at every future Windower update.* Instead of remembering a number, the plugin asks Windower's own code where it keeps your data -- a question that has the same answer on every machine, and that can be asked from the login screen, before you even pick a character. `//aio doctor` says which address it is using and where it got it from.",
      "*Et il retrouve d\xC3\xA9sormais cette adresse tout seul, \xC3\xA0 chaque future mise \xC3\xA0 jour de Windower.* Au lieu de retenir un num\xC3\xA9ro, le plugin demande au code de Windower lui-m\xC3\xAAme o\xC3\xB9 il range vos donn\xC3\xA9""es -- une question dont la r\xC3\xA9ponse est la m\xC3\xAAme sur toutes les machines, et qui peut \xC3\xAAtre pos\xC3\xA9""e d\xC3\xA8s l'\xC3\xA9""cran de login, avant m\xC3\xAAme de choisir un personnage. `//aio doctor` indique quelle adresse est utilis\xC3\xA9""e et d'o\xC3\xB9 elle vient.", CK_NEW, "HUD", "HUD" },
    { "*The recast list no longer shows a screenful of spells stuck on the same timer.* The same update moved the recast tables as well, and this one did not go quiet -- it read the neighbouring table and displayed nonsense as if it were real. Those are found on their own now too, and each one is only trusted when a second, independent check agrees with it.",
      "*La liste des recasts n'affiche plus une pleine page de sorts bloqu\xC3\xA9s sur le m\xC3\xAAme minuteur.* La m\xC3\xAAme mise \xC3\xA0 jour a aussi d\xC3\xA9plac\xC3\xA9 les tables de recast, et celle-ci ne s'est pas tue : elle lisait la table voisine et affichait n'importe quoi comme si c'\xC3\xA9tait vrai. Elles sont retrouv\xC3\xA9""es toutes seules \xC3\xA9galement, et chacune n'est accept\xC3\xA9""e que si une seconde v\xC3\xA9rification ind\xC3\xA9pendante la confirme.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_78[] = {
    { "*Odyssey counts your segments again.* Since the game update of August 12 the box drew its Sheol header with the total stuck at zero for a whole run : the message that announces a payout had been renumbered, and the plugin was still listening to the old number -- which the update had handed to an unrelated message that pays nothing. So it kept hearing something, and never heard a segment.",
      "*Odyssey compte de nouveau vos segments.* Depuis la mise \xC3\xA0 jour du jeu du 12 ao\xC3\xBBt, la bo\xC3\xAEte affichait son en-t\xC3\xAAte Sheol avec le total bloqu\xC3\xA9 \xC3\xA0 z\xC3\xA9ro pendant toute une run : le message qui annonce un gain avait \xC3\xA9t\xC3\xA9 renum\xC3\xA9rot\xC3\xA9, et le plugin \xC3\xA9""coutait toujours l'ancien num\xC3\xA9ro -- que la mise \xC3\xA0 jour avait attribu\xC3\xA9 \xC3\xA0 un message sans rapport, qui ne paie rien. Il entendait donc quelque chose, et n'entendait jamais un segment.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
    { "*And it now finds that number again on its own, at every future game update.* Two payouts are enough to prove it : what a kill paid, added to the total before it, must give the total after it -- no other message adds up that way. Nothing to type, no segment lost while it works it out, and a message that merely talks without paying can no longer pass for the right one.",
      "*Et il retrouve d\xC3\xA9sormais ce num\xC3\xA9ro tout seul, \xC3\xA0 chaque future mise \xC3\xA0 jour du jeu.* Deux gains suffisent \xC3\xA0 le prouver : ce qu'un kill a rapport\xC3\xA9, ajout\xC3\xA9 au total d'avant, doit donner le total d'apr\xC3\xA8s -- aucun autre message ne tombe juste ainsi. Rien \xC3\xA0 taper, aucun segment perdu pendant la recherche, et un message qui se contente de parler sans rien payer ne peut plus passer pour le bon.", CK_NEW, "Zone Tracker", "Zone Tracker" },
    { "Limbus gets the same treatment for its two wings. Abyssea cannot be proven the same way for now, so it says so instead : `//aio doctor` reports when the zone is talking and the plugin no longer recognises any of it.",
      "Limbus re\xC3\xA7oit le m\xC3\xAAme traitement pour ses deux ailes. Abyssea ne peut pas encore \xC3\xAAtre prouv\xC3\xA9 de la m\xC3\xAAme fa\xC3\xA7on, alors il le dit : `//aio doctor` signale quand la zone parle et que le plugin n'y reconna\xC3\xAEt plus rien.", CK_NEW, "Zone Tracker", "Zone Tracker" },
};

static const ChangeLine CL_77[] = {
    { "*The plugin now watches itself for the kind of breakage that shows no symptom.* A game update can move a value without anything going dark : the box keeps displaying a number, the number looks normal, and it is wrong. Several things are known twice -- the server sends them, and the game also keeps them in memory -- so those two are now compared, and `//aio doctor` says plainly if they stop agreeing.",
      "*Le plugin surveille d\xC3\xA9sormais lui-m\xC3\xAAme le type de casse qui ne donne aucun sympt\xC3\xB4me.* Une mise \xC3\xA0 jour du jeu peut d\xC3\xA9placer une valeur sans que rien ne s'\xC3\xA9teigne : la bo\xC3\xAEte continue d'afficher un chiffre, le chiffre a l'air normal, et il est faux. Plusieurs informations sont connues deux fois -- le serveur les envoie, et le jeu les garde aussi en m\xC3\xA9moire -- ces deux sources sont donc compar\xC3\xA9""es, et `//aio doctor` le dit clairement si elles cessent de concorder.", CK_NEW, "HUD", "HUD" },
    { "It never corrects anything on its own : when two sources disagree, nothing can tell which one is right, so guessing would be worse than saying nothing. It reports both values and leaves the decision to a human.",
      "Il ne corrige jamais rien de lui-m\xC3\xAAme : quand deux sources divergent, rien ne permet de dire laquelle a raison, et deviner serait pire que se taire. Il affiche les deux valeurs et laisse la d\xC3\xA9""cision \xC3\xA0 un humain.", CK_NEW, "HUD", "HUD" },
};

static const ChangeLine CL_76[] = {
    { "*The FFXI update of August 12 broke several boxes -- they are back.* Selecting a party member no longer highlighted their line, the Cost/Next box stayed dark, and the EXP / Master Level / merit panel showed nothing. The game update had moved the places in memory where those values live ; everything read through Windower kept working, which is why only a few things went dark while the rest looked perfectly fine.",
      "*La mise \xC3\xA0 jour de FFXI du 12 ao\xC3\xBBt avait cass\xC3\xA9 plusieurs bo\xC3\xAEtes -- elles sont de retour.* S\xC3\xA9lectionner un membre du groupe n'illuminait plus sa ligne, la bo\xC3\xAEte Co\xC3\xBBt/Next restait \xC3\xA9teinte, et le panneau EXP / Master Level / m\xC3\xA9rites n'affichait rien. La mise \xC3\xA0 jour du jeu avait d\xC3\xA9plac\xC3\xA9 les endroits en m\xC3\xA9moire o\xC3\xB9 ces valeurs se trouvent ; tout ce qui passe par Windower continuait de fonctionner, d'o\xC3\xB9 ces quelques bo\xC3\xAEtes \xC3\xA9teintes au milieu d'un ensemble qui semblait parfaitement sain.", CK_FIXED, "HUD", "HUD" },
    { "*And the plugin now repairs itself after a game update, without waiting for a new release.* It recognises that the client has changed, finds the values again on its own -- by checking them against the data the server sends, or against what you have targeted or highlighted -- and remembers the result. In practice you play, and within a few seconds to a few minutes everything is back, with nothing to type.",
      "*Et le plugin se r\xC3\xA9pare d\xC3\xA9sormais tout seul apr\xC3\xA8s une mise \xC3\xA0 jour du jeu, sans attendre une nouvelle version.* Il reconna\xC3\xAEt que le client a chang\xC3\xA9, retrouve les valeurs par lui-m\xC3\xAAme -- en les recoupant avec les donn\xC3\xA9""es envoy\xC3\xA9""es par le serveur, ou avec ce que vous ciblez et survolez -- et retient le r\xC3\xA9sultat. En pratique vous jouez, et en quelques secondes \xC3\xA0 quelques minutes tout est revenu, sans rien taper.", CK_NEW, "HUD", "HUD" },
    { "*The Cost/Next box no longer shows an empty frame while it is still working out where to read.* An empty frame already means \"nothing to display here\" (a job with no magic, for instance), so it now stays hidden rather than looking broken.",
      "*La bo\xC3\xAEte Co\xC3\xBBt/Next n'affiche plus un cadre vide pendant qu'elle cherche encore o\xC3\xB9 lire.* Un cadre vide veut d\xC3\xA9j\xC3\xA0 dire \" rien \xC3\xA0 afficher ici \" (un job sans magie, par exemple), elle reste donc masqu\xC3\xA9""e au lieu de sembler cass\xC3\xA9""e.", CK_FIXED, "Party", "Groupe" },
    { "Note for anyone still on the old build : if a box stays dark after a game update, `//aio doctor` now names exactly which value cannot be read and what to do about it.",
      "Note pour ceux rest\xC3\xA9s sur l'ancienne version : si une bo\xC3\xAEte reste \xC3\xA9teinte apr\xC3\xA8s une mise \xC3\xA0 jour du jeu, `//aio doctor` nomme d\xC3\xA9sormais pr\xC3\xA9""cis\xC3\xA9ment la valeur illisible et la marche \xC3\xA0 suivre.", CK_IMPROVED, "HUD", "HUD" },
};

static const ChangeLine CL_75[] = {
    { "*If you are updating from 1.0.73 or older, this one update runs your OLD updater.* That version could, in rare cases, leave you with no plugin file at all if anything interrupted it. If that happens, re-extract the zip from the release page once -- every update after this one is protected.",
      "*Si vous mettez \xC3\xA0 jour depuis la 1.0.73 ou plus ancienne, cette mise \xC3\xA0 jour utilise votre ANCIEN updater.* Cette version pouvait, dans de rares cas, vous laisser sans aucun fichier plugin si quelque chose l'interrompait. Si cela arrive, re-extrayez le zip depuis la page de release une fois -- toutes les mises \xC3\xA0 jour suivantes sont prot\xC3\xA9g\xC3\xA9""es.", CK_IMPROVED, "Update", "Mise \xC3\xA0 jour" },
    { "*The distance to a party member no longer freezes when they run far away.* Past about 50 yalms the game stops tracking them, and their last position stayed on screen as a normal-looking number that never changed again. Their line now shows *50+* in red instead, and goes back to the exact distance the moment they are back in range.",
      "*La distance d'un membre du groupe ne se fige plus quand il s'\xC3\xA9loigne.* Au-del\xC3\xA0 d'environ 50 yalms le jeu cesse de le suivre, et sa derni\xC3\xA8re position restait affich\xC3\xA9""e comme un chiffre normal qui ne bougeait plus jamais. Sa ligne affiche d\xC3\xA9sormais *50+* en rouge, et retrouve la distance exacte d\xC3\xA8s qu'il revient \xC3\xA0 portee.", CK_FIXED, "Party", "Groupe" },
    { "*Buffs you cast on allies stop disappearing over a long session.* The list of what each member is carrying had a fixed number of slots that were never freed, and trusts take a new one every time you re-summon them. Once it filled up, most members' rows were simply not drawn and their expiry alerts went silent.",
      "*Les buffs que vous lancez sur vos alli\xC3\xA9s ne disparaissent plus au fil d'une longue session.* La liste de ce que porte chaque membre avait un nombre de places fixe, jamais lib\xC3\xA9r\xC3\xA9""es, et les trusts en prennent une nouvelle \xC3\xA0 chaque re-invocation. Une fois pleine, les lignes de la plupart des membres n'\xC3\xA9taient tout simplement plus dessin\xC3\xA9""es et leurs alertes d'expiration devenaient muettes.", CK_FIXED, "Timers", "Timers" },
    { "*Expiry alerts no longer stay on screen for a category you turned off*, and watching allies during an alliance no longer uses up the alert slots your own buffs need.",
      "*Les alertes d'expiration ne restent plus affich\xC3\xA9""es pour une cat\xC3\xA9gorie que vous avez d\xC3\xA9sactiv\xC3\xA9""e*, et le suivi des alli\xC3\xA9s en alliance ne consomme plus les places dont vos propres buffs ont besoin.", CK_FIXED, "Timers", "Timers" },
    { "*Limbus remembers your run across a plugin reload*, and your coffer history is no longer wiped by an update. The runs-left count and the quadrant chips come back instead of showing \"?\".",
      "*Limbus se souvient de votre run apr\xC3\xA8s un rechargement du plugin*, et votre historique de coffres n'est plus effac\xC3\xA9 par une mise \xC3\xA0 jour. Le nombre de runs restants et les pastilles de quadrant reviennent au lieu d'afficher \" ? \".", CK_FIXED, "Zone Tracker", "Zone Tracker" },
    { "*Omen shows its bonus objectives instead of hiding them.* On the first floor the box had read the objectives correctly and then dropped them, until the game happened to repeat its floor announcement. Treasure floors are also recognised whatever way the game spells them.",
      "*Omen affiche ses objectifs bonus au lieu de les masquer.* Au premier \xC3\xA9tage la bo\xC3\xAEte lisait pourtant correctement les objectifs puis les jetait, jusqu'\xC3\xA0 ce que le jeu r\xC3\xA9p\xC3\xA8te son annonce d'\xC3\xA9tage. Les \xC3\xA9tages \xC3\xA0 coffres sont aussi reconnus quelle que soit la fa\xC3\xA7on dont le jeu les \xC3\xA9""crit.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
    { "*Text stays sharp after you open the settings.* Opening the panel over a visible HUD used up every cached text size, and everything drawn afterwards was stretched from the nearest one instead. Map and party icons were also slightly softened by the same kind of leftover.",
      "*Le texte reste net apr\xC3\xA8s l'ouverture des r\xC3\xA9glages.* Ouvrir le panneau par-dessus un HUD visible consommait toutes les tailles de texte en cache, et tout ce qui \xC3\xA9tait dessin\xC3\xA9 ensuite \xC3\xA9tait \xC3\xA9tir\xC3\xA9 depuis la plus proche. Les ic\xC3\xB4nes de la carte et du groupe \xC3\xA9taient adoucies par un r\xC3\xA9sidu du m\xC3\xAAme genre.", CK_FIXED, "HUD", "HUD" },
    { "*Deleting the profile you are using now really deactivates it.* It stayed marked as active, and saving afterwards silently recreated it. A profile that cannot be written to disk now says so instead of pretending it was saved.",
      "*Supprimer le profil que vous utilisez le d\xC3\xA9sactive vraiment.* Il restait marqu\xC3\xA9 comme actif, et enregistrer ensuite le recr\xC3\xA9""ait en silence. Un profil qui ne peut pas \xC3\xAAtre \xC3\xA9""crit sur le disque le dit d\xC3\xA9sormais, au lieu de faire croire qu'il a \xC3\xA9t\xC3\xA9 enregistr\xC3\xA9.", CK_FIXED, "Profiles", "Profils" },
    { "*Updating with two clients open no longer reports a false failure.* Both would install at once and the loser overwrote the winner's result, so you were told the update had failed when it had actually worked. Only one installs now. An update that really fails also leaves a log next to the plugin, so it can be diagnosed.",
      "*Mettre \xC3\xA0 jour avec deux clients ouverts ne signale plus un faux \xC3\xA9""chec.* Les deux installaient en m\xC3\xAAme temps et le perdant \xC3\xA9""crasait le r\xC3\xA9sultat du gagnant, donc on vous annon\xC3\xA7""ait un \xC3\xA9""chec alors que tout avait fonctionne. Un seul installe d\xC3\xA9sormais. Une mise \xC3\xA0 jour qui \xC3\xA9""choue vraiment laisse aussi un journal \xC3\xA0 c\xC3\xB4t\xC3\xA9 du plugin, pour pouvoir \xC3\xAAtre diagnostiqu\xC3\xA9""e.", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
    { "Monster ability names were out of date : several showed the wrong name and a few recent ones were missing entirely.",
      "Les noms de capacit\xC3\xA9s de monstres \xC3\xA9taient p\xC3\xA9rim\xC3\xA9s : plusieurs affichaient un nom erron\xC3\xA9 et quelques r\xC3\xA9""cents manquaient compl\xC3\xA8tement.", CK_FIXED, "Target", "Cible" },
    { "Under the hood : the window skin, the settings and several readings of game memory now report a failure instead of failing silently, and the build no longer produces any warning at all -- so a new one cannot hide among the old.",
      "Sous le capot : l'habillage des fen\xC3\xAAtres, les r\xC3\xA9glages et plusieurs lectures de la m\xC3\xA9moire du jeu signalent d\xC3\xA9sormais un \xC3\xA9""chec au lieu d'\xC3\xA9""chouer en silence, et la compilation ne produit plus aucun avertissement -- ainsi un nouveau ne peut plus se cacher parmi les anciens.", CK_IMPROVED, "HUD", "HUD" },
};
static const ChangeLine CL_74[] = {
    { "*An update that fails can no longer leave you without the plugin.* The new build was unpacked straight over your Windower folder, and that operation deletes each file before rewriting it -- then undoes itself if anything goes wrong along the way. So a single file it could not write, anywhere in the fourteen hundred that ship, could end with no AioHud at all : the HUD closed, and Windower answered \"File does not exist\" when it tried to come back. The download is now verified and unpacked aside first, while the HUD is still running ; your folder is only touched once the new build is known to be complete, and the plugin itself is replaced last, from a copy that is put back if that step fails. Whatever happens, a failed update now leaves your install exactly as it was.",
      "*Une mise \xC3\xA0 jour qui \xC3\xA9""choue ne peut plus vous laisser sans le plugin.* La nouvelle version \xC3\xA9tait d\xC3\xA9""compress\xC3\xA9""e directement par-dessus votre dossier Windower, et cette op\xC3\xA9ration supprime chaque fichier avant de le r\xC3\xA9\xC3\xA9""crire -- puis d\xC3\xA9""fait tout si quoi que ce soit se passe mal en chemin. Un seul fichier impossible \xC3\xA0 \xC3\xA9""crire, parmi les quatorze cents livres, pouvait donc ne laisser aucun AioHud : le HUD se fermait, et Windower r\xC3\xA9pondait \"File does not exist\" au moment de le relancer. Le t\xC3\xA9l\xC3\xA9""chargement est d\xC3\xA9sormais v\xC3\xA9rifi\xC3\xA9 et d\xC3\xA9""compress\xC3\xA9 \xC3\xA0 c\xC3\xB4t\xC3\xA9 d'abord, pendant que le HUD tourne encore ; votre dossier n'est touch\xC3\xA9 qu'une fois la nouvelle version reconnue compl\xC3\xA8te, et le plugin lui-m\xC3\xAAme est remplac\xC3\xA9 en dernier, \xC3\xA0 partir d'une copie qui est restaur\xC3\xA9""e si cette \xC3\xA9tape \xC3\xA9""choue. Quoi qu'il arrive, une mise \xC3\xA0 jour rat\xC3\xA9""e laisse maintenant votre installation exactement dans l'\xC3\xA9tat o\xC3\xB9 elle \xC3\xA9tait.", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
    { "*And it now tells you why.* The reason an update did not go through was written to a file nobody reads : all you saw was the HUD closing and an error from Windower that named nothing. It is now said in chat, along with what to do about it.",
      "*Et elle vous dit d\xC3\xA9sormais pourquoi.* La raison pour laquelle une mise \xC3\xA0 jour n'est pas pass\xC3\xA9""e \xC3\xA9tait \xC3\xA9""crite dans un fichier que personne ne lit : vous ne voyiez que le HUD se fermer et une erreur de Windower qui ne nommait rien. Elle est maintenant annonc\xC3\xA9""e dans le chat, avec la marche \xC3\xA0 suivre.", CK_IMPROVED, "Update", "Mise \xC3\xA0 jour" },
    { "A plugin that is missing while its folder is still there is now reported as an install to repair, instead of being taken for a deliberate removal -- which used to make the updater quietly take its own startup line back out.",
      "Un plugin absent dont le dossier est encore la est d\xC3\xA9sormais signal\xC3\xA9 comme une installation \xC3\xA0 r\xC3\xA9parer, au lieu d'\xC3\xAAtre pris pour une suppression volontaire -- ce qui amenait la mise \xC3\xA0 jour \xC3\xA0 retirer discretement sa propre ligne de d\xC3\xA9marrage.", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
};
static const ChangeLine CL_73[] = {
    { "*A job ability no longer opens a skillchain with a weaponskill's properties.* Shield Bash and Expiacion carry the same internal number, and so do Weapon Bash and Ruinator, Jump and Gale Axe : using Shield Bash opened a resonance window under Expiacion's element, so the closer it suggested was wrong. They are told apart by what the game announces, which is the only thing that differs between them -- and it was measured on eleven weaponskills rather than assumed. The weaponskill popup already knew this rule ; the Skillchains box did not.",
      "*Une capacit\xC3\xA9 de job n'ouvre plus un skillchain avec les propri\xC3\xA9t\xC3\xA9s d'une attaque sp\xC3\xA9""ciale.* Shield Bash et Expiacion portent le m\xC3\xAAme num\xC3\xA9ro interne, comme Weapon Bash et Ruinator, ou Jump et Gale Axe : utiliser Shield Bash ouvrait une fen\xC3\xAAtre de r\xC3\xA9sonance sous l'\xC3\xA9l\xC3\xA9ment d'Expiacion, et la cl\xC3\xB4ture propos\xC3\xA9""e \xC3\xA9tait donc fausse. Ils sont d\xC3\xA9sormais distingu\xC3\xA9s par ce que le jeu annonce, la seule chose qui diff\xC3\xA8re entre eux -- et cela a \xC3\xA9t\xC3\xA9 mesur\xC3\xA9 sur onze attaques sp\xC3\xA9""ciales, pas suppos\xC3\xA9. Le popup d'attaque sp\xC3\xA9""ciale connaissait d\xC3\xA9j\xC3\xA0 cette r\xC3\xA8gle ; la bo\xC3\xAEte Skillchains non.", CK_FIXED, "Skillchains", "Skillchains" },
    { "*The Limbus weekly allowance no longer vanishes when you leave the zone.* How many data collections you have left in the week is account-wide, shared between Apollyon and Temenos, but it was only remembered while you stayed inside -- stepping out and coming back showed nothing. It is now kept with the date it was seen : a count from an earlier week reports a full allowance again after the Sunday reset instead of a stale number, and a count that has never been seen shows a question mark rather than a plausible guess.",
      "*L'allocation hebdomadaire de Limbus ne dispara\xC3\xAEt plus quand vous quittez la zone.* Le nombre de collectes de donn\xC3\xA9""es qu'il vous reste dans la semaine est li\xC3\xA9 au compte, partag\xC3\xA9 entre Apollyon et Temenos, mais il n'\xC3\xA9tait retenu que le temps o\xC3\xB9 vous restiez \xC3\xA0 l'int\xC3\xA9rieur -- sortir et revenir n'affichait plus rien. Il est d\xC3\xA9sormais conserv\xC3\xA9 avec la date \xC3\xA0 laquelle il a \xC3\xA9t\xC3\xA9 vu : un compte d'une semaine pr\xC3\xA9""c\xC3\xA9""dente redonne une allocation compl\xC3\xA8te apr\xC3\xA8s la r\xC3\xA9initialisation du dimanche, au lieu d'un nombre p\xC3\xA9rim\xC3\xA9, et un compte jamais observ\xC3\xA9 affiche un point d'interrogation plut\xC3\xB4t qu'une valeur plausible.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
    { "*Omen : the bonus objectives of each floor are listed, with their progress.* They are read from what the game announces, floor by floor. A floor carrying fewer objectives than the previous one no longer leaves the extra lines of the old floor behind, and boss or treasure floors correctly show none.",
      "*Omen : les objectifs bonus de chaque \xC3\xA9tage sont listes, avec leur progression.* Ils sont lus depuis ce que le jeu annonce, \xC3\xA9tage par \xC3\xA9tage. Un \xC3\xA9tage comportant moins d'objectifs que le pr\xC3\xA9""c\xC3\xA9""dent ne laisse plus tra\xC3\xAEner les lignes en trop de l'ancien \xC3\xA9tage, et les \xC3\xA9tages de boss ou de tr\xC3\xA9sor n'en affichent aucun, correctement.", CK_NEW, "Zone Tracker", "Zone Tracker" },
};
static const ChangeLine CL_72[] = {
    { "*A resisted spell is no longer shown as if it had landed.* Casting Distract on a target that resists it -- or an Elegy on an earth elemental -- still put the debuff in the box, with a full countdown. The game announces a resist in a different way from a plain \"no effect\", and only that second one was recognised : every other way it has of saying nothing happened was being read as a success. All of them are now understood, on debuffs and on buffs alike.",
      "*Un sort r\xC3\xA9sist\xC3\xA9 n'est plus affich\xC3\xA9 comme s'il avait pris.* Lancer un Distract sur une cible qui y r\xC3\xA9siste -- ou une Elegy sur un elemental de terre -- ajoutait quand m\xC3\xAAme le debuff dans la bo\xC3\xAEte, avec un d\xC3\xA9""compte complet. Le jeu annonce un resist autrement qu'un simple \"aucun effet\", et seul ce second cas \xC3\xA9tait reconnu : toutes les autres fa\xC3\xA7ons qu'il a de dire que rien ne s'est pass\xC3\xA9 \xC3\xA9taient lues comme une r\xC3\xA9ussite. Elles sont d\xC3\xA9sormais toutes comprises, sur les debuffs comme sur les buffs.", CK_FIXED, "Debuffs", "Debuffs" },
    { "*Changing job now clears the buffs you had put on your party.* Your own buffs vanish on a job change because the game removes them, but the ones you had cast on the others kept counting down -- and on BRD, the time left on a Regen you cast as SCH is not something you are going to act on. They now leave with the job, along with any alert watching them. Changing only your support job keeps them, since you can still recast.",
      "*Changer de job efface d\xC3\xA9sormais les buffs que vous aviez pos\xC3\xA9s sur votre groupe.* Vos propres buffs disparaissent lors d'un changement de job parce que le jeu les retire, mais ceux que vous aviez lanc\xC3\xA9s sur les autres continuaient leur d\xC3\xA9""compte -- et en BRD, le temps restant d'un Regen lanc\xC3\xA9 en SCH n'est pas une information sur laquelle vous allez agir. Ils s'en vont maintenant avec le job, ainsi que toute alerte qui les surveillait. Changer seulement de job de support les conserve, puisque vous pouvez toujours relancer.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_71[] = {
    { "*The updater now checks the download before installing it.* Each release is published with a checksum, and the update is compared against it and refused if it does not match -- nothing is written over your Windower folder unless the file is exactly the one that was built. If a release ever arrives without a checksum, the update stops and says so rather than installing on trust.",
      "*La mise \xC3\xA0 jour v\xC3\xA9rifie d\xC3\xA9sormais le t\xC3\xA9l\xC3\xA9""chargement avant de l'installer.* Chaque version est publi\xC3\xA9""e avec une empreinte, la mise \xC3\xA0 jour est compar\xC3\xA9""e \xC3\xA0 celle-ci et refus\xC3\xA9""e si elle ne correspond pas -- rien n'est \xC3\xA9""crit dans votre dossier Windower tant que le fichier n'est pas exactement celui qui a \xC3\xA9t\xC3\xA9 compile. Si une version arrive un jour sans empreinte, la mise \xC3\xA0 jour s'arr\xC3\xAAte et le dit, plut\xC3\xB4t que d'installer sur parole.", CK_NEW, "Update", "Mise \xC3\xA0 jour" },
    { "*Removing AioHud no longer leaves Windower loading something that is not there.* The plugin adds a line to Windower's startup file so its updater loads with the game, and nothing ever removed it : deleting AioHud left Windower trying to load a missing add-on at every launch, forever, with no way to tell where it came from. The companion add-on now takes its own line back out when it sees the plugin is gone.",
      "*D\xC3\xA9sinstaller AioHud ne laisse plus Windower charger quelque chose qui n'existe plus.* Le plugin ajoute une ligne au fichier de d\xC3\xA9marrage de Windower pour que son updater se charge avec le jeu, et rien ne l'enlevait jamais : supprimer AioHud laissait Windower tenter de charger un add-on absent \xC3\xA0 chaque lancement, ind\xC3\xA9""finiment, sans moyen de savoir d'o\xC3\xB9 \xC3\xA7""a venait. L'add-on compagnon retire d\xC3\xA9sormais sa propre ligne quand il constate que le plugin n'est plus l\xC3\xA0.", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
    { "*Resizing a box is smooth again.* Every single frame of a slider drag was rewriting your whole settings file and, for a box placed by the layout, rebuilding every element of the HUD -- reloading its images and re-reading the zone map along the way. The box still follows the slider exactly as before ; the saving and the rebuilding now happen once, when you stop moving it.",
      "*Redimensionner une bo\xC3\xAEte est de nouveau fluide.* Chaque image d'un d\xC3\xA9placement de curseur r\xC3\xA9\xC3\xA9""crivait tout votre fichier de r\xC3\xA9glages et, pour une bo\xC3\xAEte plac\xC3\xA9""e par la mise en page, reconstruisait chaque \xC3\xA9l\xC3\xA9ment du HUD -- en rechargeant ses images et en relisant la carte de zone au passage. La bo\xC3\xAEte suit toujours le curseur exactement comme avant ; l'enregistrement et la reconstruction n'ont plus lieu qu'une fois, quand vous arr\xC3\xAAtez de la bouger.", CK_FIXED, "Config", "Config" },
    { "*The diagnostic log no longer erases itself, and no longer balloons.* It was wiped every time the plugin was loaded -- so unloading and reloading to see if a problem went away destroyed the record of that very problem, and so did every update. It is kept now, with the version and the time at the top of each session. A diagnostic line that was meant to appear a handful of times per session was also repeating on every frame once it had seen enough different cases : one real session had produced a 22 MB file.",
      "*Le journal de diagnostic ne s'efface plus, et ne gonfle plus.* Il \xC3\xA9tait vide \xC3\xA0 chaque chargement du plugin -- donc d\xC3\xA9""charger et recharger pour voir si un probl\xC3\xA8me avait disparu d\xC3\xA9truisait la trace de ce probl\xC3\xA8me, et chaque mise \xC3\xA0 jour faisait de m\xC3\xAAme. Il est d\xC3\xA9sormais conserv\xC3\xA9, avec la version et l'heure en t\xC3\xAAte de chaque session. Une ligne de diagnostic cens\xC3\xA9""e appara\xC3\xAEtre quelques fois par session se r\xC3\xA9p\xC3\xA9tait par ailleurs \xC3\xA0 chaque image d\xC3\xA8s qu'elle avait vu assez de cas diff\xC3\xA9rents : une session r\xC3\xA9""elle avait produit un fichier de 22 Mo.", CK_FIXED, "HUD", "HUD" },
    { "Two smaller display fixes : the bright edge at the tip of the target's HP bar no longer disappears when the bar is set very thin, and the Minimap samples in the Help tab no longer stay blank for the rest of the session if their images happen to miss on the first try.",
      "Deux corrections d'affichage plus modestes : le liser\xC3\xA9 clair au bout de la barre de vie de la cible ne dispara\xC3\xAEt plus quand la barre est r\xC3\xA9gl\xC3\xA9""e tr\xC3\xA8s fine, et les aper\xC3\xA7us de Minicarte de l'onglet Aide ne restent plus vides pour le reste de la session si leurs images \xC3\xA9""chouent au premier essai.", CK_FIXED, "HUD", "HUD" },
};
static const ChangeLine CL_70[] = {
    { "*Buffs put on you by a trust no longer survive the \"me + players\" filter.* A Protect, Shell or Regen applied by a trust could keep showing -- sometimes named after a party member who had cast the same spell much earlier in the session, which is exactly why it slipped through. Two separate causes were behind it : a trust that had been dismissed or re-summoned was no longer recognised as a trust at all, and an old cast could out-rank the correct, more recent one.",
      "*Les buffs qu'un trust vous pose ne survivent plus au filtre \"moi + joueurs\".* Un Protect, Shell ou Regen appliqu\xC3\xA9 par un trust pouvait rester affich\xC3\xA9 -- parfois au nom d'un membre du groupe qui avait lanc\xC3\xA9 le m\xC3\xAAme sort bien plus t\xC3\xB4t dans la session, ce qui est pr\xC3\xA9""cis\xC3\xA9ment ce qui lui permettait de passer. Deux causes distinctes : un trust renvoy\xC3\xA9 ou re-invoque n'\xC3\xA9tait plus reconnu comme trust du tout, et un ancien lancement pouvait l'emporter sur l'attribution correcte, plus r\xC3\xA9""cente.", CK_FIXED, "Timers", "Timers" },
    { "*Shield Bash and Weapon Bash no longer trigger the Arcade WS banner under a weaponskill's name.* Those abilities share their internal number with a real weaponskill -- Shield Bash with Expiacion -- so the banner announced the wrong one. The rule now recognises real weaponskills instead of trying to list every ability that is not one : anything unrecognised stays silent rather than showing a wrong name.",
      "*Shield Bash et Weapon Bash ne d\xC3\xA9""clenchent plus la banni\xC3\xA8re Arcade WS sous le nom d'un weaponskill.* Ces capacit\xC3\xA9s partagent leur num\xC3\xA9ro interne avec un vrai weaponskill -- Shield Bash avec Expiacion -- d'o\xC3\xB9 le mauvais nom annonc\xC3\xA9. La r\xC3\xA8gle reconna\xC3\xAEt d\xC3\xA9sormais les vrais weaponskills au lieu d'essayer d'\xC3\xA9num\xC3\xA9rer toutes les capacit\xC3\xA9s qui n'en sont pas : ce qui n'est pas reconnu reste silencieux plut\xC3\xB4t que d'afficher un nom faux.", CK_FIXED, "Arcade WS", "Arcade WS" },
    { "*A damaged settings file can no longer crash the game.* One value of the Minimap settings was printed without any length check, so an out-of-range number -- from a hand-edited or corrupted file -- ended the game process the moment the Minimap tab was opened. The value is now bounded when the file is read and when it is displayed.",
      "*Un fichier de r\xC3\xA9glages ab\xC3\xAEm\xC3\xA9 ne peut plus faire planter le jeu.* Une valeur des r\xC3\xA9glages Minicarte \xC3\xA9tait affich\xC3\xA9""e sans aucun contr\xC3\xB4le de longueur : un nombre hors plage -- fichier \xC3\xA9""dit\xC3\xA9 \xC3\xA0 la main ou corrompu -- terminait le processus du jeu d\xC3\xA8s l'ouverture de l'onglet Minicarte. La valeur est d\xC3\xA9sormais born\xC3\xA9""e \xC3\xA0 la lecture du fichier et \xC3\xA0 l'affichage.", CK_FIXED, "Config", "Config" },
    { "After about 25 days without restarting the PC, two things quietly stopped retrying : the zone-map tables and the shared-profile follow-up. Both work again at any uptime.",
      "Apr\xC3\xA8s environ 25 jours sans red\xC3\xA9marrer le PC, deux choses cessaient discretement de r\xC3\xA9""essayer : les tables de cartes de zone et le suivi des profils partag\xC3\xA9s. Les deux fonctionnent de nouveau quelle que soit la dur\xC3\xA9""e de fonctionnement.", CK_FIXED, "HUD", "HUD" },
    { "For testers : every line of the diagnostic log now says which character wrote it, so a capture taken with two clients running can still be read.",
      "Pour les testeurs : chaque ligne du journal de diagnostic indique d\xC3\xA9sormais quel personnage l'a \xC3\xA9""crite, afin qu'une capture prise avec deux clients ouverts reste lisible.", CK_NEW, "HUD", "HUD" },
};
static const ChangeLine CL_69[] = {
    { "*A black minimap, or raw item numbers instead of gear icons, no longer last until you zone or restart.* When a game file is momentarily unreadable -- typically while the zone is loading and the disk is busy, or when an antivirus touches it for the first time -- the plugin retried for a few seconds and then stopped for good : the map stayed black for your whole visit to that zone, and an equipment slot kept showing a number for the rest of the session. It now keeps retrying quietly in the background, so it repairs itself within seconds instead.",
      "*Une minicarte noire, ou des num\xC3\xA9ros d'objet \xC3\xA0 la place des ic\xC3\xB4nes d'\xC3\xA9quipement, ne durent plus jusqu'au changement de zone ou au red\xC3\xA9marrage.* Quand un fichier du jeu est momentan\xC3\xA9ment illisible -- typiquement pendant le chargement d'une zone quand le disque travaille, ou quand un antivirus y touche pour la premi\xC3\xA8re fois -- le plugin r\xC3\xA9""essayait quelques secondes puis abandonnait d\xC3\xA9""finitivement : la carte restait noire tout le temps pass\xC3\xA9 dans la zone, et un emplacement d'\xC3\xA9quipement affichait un num\xC3\xA9ro jusqu'\xC3\xA0 la fin de la session. Il continue d\xC3\xA9sormais de r\xC3\xA9""essayer discretement en arri\xC3\xA8re-plan, et se r\xC3\xA9pare donc tout seul en quelques secondes.", CK_FIXED, "HUD", "HUD" },
    { "Nothing changes when everything works : the quick retries are untouched, only the giving-up part was removed.",
      "Rien ne change quand tout fonctionne : les tentatives rapides sont inchang\xC3\xA9""es, seul l'abandon d\xC3\xA9""finitif a \xC3\xA9t\xC3\xA9 retir\xC3\xA9.", CK_IMPROVED, "HUD", "HUD" },
    { "The icons in a module's Help tab could stay missing for the whole session if the very first attempt to load them failed.",
      "Les ic\xC3\xB4nes de l'onglet Aide d'un module pouvaient rester absentes toute la session si la toute premi\xC3\xA8re tentative de chargement \xC3\xA9""chouait.", CK_FIXED, "Config", "Config" },
    { "The status-icon sheet is now loaded once and shared by every box instead of being loaded separately by each one -- around 13 MB less video memory in a normal session.",
      "La planche d'ic\xC3\xB4nes d'\xC3\xA9tat est d\xC3\xA9sormais charg\xC3\xA9""e une seule fois et partag\xC3\xA9""e par toutes les bo\xC3\xAEtes au lieu d'\xC3\xAAtre charg\xC3\xA9""e s\xC3\xA9par\xC3\xA9ment par chacune -- environ 13 Mo de m\xC3\xA9moire vid\xC3\xA9o en moins dans une session normale.", CK_IMPROVED, "HUD", "HUD" },
    { "For testers : when an equipment icon cannot be built at all, the log now says so on a released build (it only did on a development one), and says which step failed.",
      "Pour les testeurs : quand une ic\xC3\xB4ne d'\xC3\xA9quipement ne peut pas \xC3\xAAtre construite du tout, le journal le dit d\xC3\xA9sormais sur une version publi\xC3\xA9""e (il ne le faisait que sur une version de d\xC3\xA9veloppement), et pr\xC3\xA9""cise quelle \xC3\xA9tape a \xC3\xA9""chou\xC3\xA9.", CK_IMPROVED, "HUD", "HUD" },
};
static const ChangeLine CL_68[] = {
    { "*A Geomancy aura you replaced no longer stays flagged as lost.* You carry only one Indi- at a time, so casting another one replaces it -- but Timers read the old one leaving as a loss and kept a permanent red OUT for it. Casting Indi-Fury, then Indi-Refresh, then Indi-Regen left the first two alerting for good. Only the Indi- you are actually carrying can raise that alert now ; one that really expires still does.",
      "*Une aura de g\xC3\xA9omancie que vous avez remplac\xC3\xA9""e ne reste plus signal\xC3\xA9""e comme perdue.* Vous ne portez qu'un seul Indi- \xC3\xA0 la fois, donc en lancer un autre remplace le pr\xC3\xA9""c\xC3\xA9""dent -- mais Timers lisait le d\xC3\xA9part de l'ancien comme une perte et gardait une alerte rouge OUT permanente. Lancer Indi-Fury, puis Indi-Refresh, puis Indi-Regen laissait les deux premiers en alerte d\xC3\xA9""finitivement. Seul l'Indi- que vous portez r\xC3\xA9""ellement peut d\xC3\xA9""clencher cette alerte maintenant ; un Indi- qui expire vraiment la d\xC3\xA9""clenche toujours.", CK_FIXED, "Timers", "Timers" },
    { "Same for an Indi- placed on an ally with Entrust : replacing it with another one is a swap, not a loss.",
      "Idem pour un Indi- pos\xC3\xA9 sur un alli\xC3\xA9 avec Entrust : le remplacer par un autre est un \xC3\xA9""change, pas une perte.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_67[] = {
    { "*Your songs on allies had the wrong duration -- by a lot.* An ally's row could read 3:43 for a Minuet that really lasts 5:42. The gear that lengthens a song was only half counted : a point of \"Song+\" potency also grants +10% duration, and that half was ignored, along with every modern instrument. Measured against the game's own timer, ally song rows now land within about a second on every song tested.",
      "*Vos chants sur les alli\xC3\xA9s affichaient une dur\xC3\xA9""e fausse -- de beaucoup.* La ligne d'un alli\xC3\xA9 pouvait indiquer 3:43 pour un Minuet qui dure r\xC3\xA9""ellement 5:42. L'\xC3\xA9quipement qui allonge un chant n'\xC3\xA9tait compt\xC3\xA9 qu'\xC3\xA0 moiti\xC3\xA9 : un point de potence \"Song+\" donne aussi +10% de dur\xC3\xA9""e, et cette moiti\xC3\xA9 \xC3\xA9tait ignor\xC3\xA9""e, ainsi que tous les instruments modernes. Compar\xC3\xA9 au timer du jeu lui-m\xC3\xAAme, les lignes alli\xC3\xA9""es tombent maintenant \xC3\xA0 la seconde pr\xC3\xA8s sur tous les chants test\xC3\xA9s.", CK_FIXED, "Timers", "Timers" },
    { "Why it was invisible for so long : a song sung on the whole party lands on YOU too, and those rows show your own exact server timer. Only a Pianissimo on a single ally reveals the estimate -- which is where the gap finally showed.",
      "Pourquoi c'est rest\xC3\xA9 invisible si longtemps : un chant lanc\xC3\xA9 sur tout le groupe vous touche AUSSI, et ces lignes affichent votre propre timer serveur exact. Seul un Pianissimo sur un alli\xC3\xA9 isol\xC3\xA9 r\xC3\xA9v\xC3\xA8le l'estimation -- c'est l\xC3\xA0 que l'\xC3\xA9""cart a fini par appara\xC3\xAEtre.", CK_FIXED, "Timers", "Timers" },
    { "A buff cast on ONE ally could show a group count that included people who never received it -- a Protectra V on the party followed by a Protect V on one person displayed \"(AoE 6)\" on a row that covered a single ally.",
      "Un buff lanc\xC3\xA9 sur UN seul alli\xC3\xA9 pouvait afficher un compteur de groupe incluant des gens qui ne l'avaient pas re\xC3\xA7u -- un Protectra V sur le groupe suivi d'un Protect V sur une personne affichait \"(AoE 6)\" sur une ligne qui ne couvrait qu'un alli\xC3\xA9.", CK_FIXED, "Timers", "Timers" },
    { "A trust carrying a Protect and a Shell cast by someone else slipped through the \"my buffs only\" filter.",
      "Un trust portant un Protect et un Shell lanc\xC3\xA9s par quelqu'un d'autre passait au travers du filtre \"mes buffs uniquement\".", CK_FIXED, "Timers", "Timers" },
    { "On a busy action packet -- many effects on one target -- the following targets could be read wrong, so a buff or debuff landing on them was occasionally missed.",
      "Sur un paquet d'action charg\xC3\xA9 -- beaucoup d'effets sur une m\xC3\xAAme cible -- les cibles suivantes pouvaient \xC3\xAAtre mal lues, et un buff ou un debuff qui les touchait \xC3\xA9tait parfois manqu\xC3\xA9.", CK_FIXED, "HUD", "HUD" },
};

static const ChangeLine CL_66[] = {
    { "*The Debuffs box now shows which TIER is on the mob.* A Dia III reads \"Dia III\", not just \"Dia\" -- and it works whoever cast it, yours or a party member's. A debuff replaced by a stronger one (Bio III over your Dia III) now disappears the way the game replaced it, instead of lingering with a dead countdown.",
      "*La bo\xC3\xAEte Debuffs indique maintenant quel PALIER est sur le mob.* Un Dia III affiche \"Dia III\", plus seulement \"Dia\" -- et \xC3\xA7""a marche quel que soit le lanceur, vous ou un membre du groupe. Un debuff remplac\xC3\xA9 par un plus fort (Bio III sur votre Dia III) dispara\xC3\xAEt comme le jeu l'a remplac\xC3\xA9, au lieu de tra\xC3\xAEner avec un d\xC3\xA9""compte mort.", CK_NEW, "Debuffs", "Debuffs" },
    { "*Corsair Quick Draw is marked.* A Light Shot on a Dia, or a Dark Shot on a Bio, reinforces it without changing its tier -- so the row keeps its real tier and gets a small red reticle. The mark clears as soon as the spell is recast.",
      "*Les Quick Draw du Corsair sont signal\xC3\xA9s.* Un Light Shot sur un Dia, ou un Dark Shot sur un Bio, le renforce sans changer son palier -- la ligne garde donc son vrai palier et re\xC3\xA7oit un petit r\xC3\xA9ticule rouge. La marque dispara\xC3\xAEt d\xC3\xA8s que le sort est relanc\xC3\xA9.", CK_NEW, "Debuffs", "Debuffs" },
    { "*Your buffs on allies no longer vanish on area casts.* A Protectra V on six people, a Horde song or a Corsair roll on the party could silently drop every ally row but the first. All the rows show up now, and they stay locked to your own exact timer.",
      "*Vos buffs sur alli\xC3\xA9s ne disparaissent plus sur les sorts de zone.* Un Protectra V \xC3\xA0 six, un chant Horde ou un roll de Corsair sur le groupe pouvait faire dispara\xC3\xAEtre en silence toutes les lignes alli\xC3\xA9""es sauf la premi\xC3\xA8re. Toutes s'affichent maintenant, et restent cal\xC3\xA9""es sur votre propre timer exact.", CK_FIXED, "Timers", "Timers" },
    { "*Ally buffs stay honest with the box closed.* Hiding the Timers box, or unticking \"My buffs on allies\", used to freeze the check that drops a buff dispelled or overwritten early -- so reopening the box showed buffs that were long gone. That upkeep now runs whatever is displayed. Ally countdowns also read to the same second as your own rows.",
      "*Les buffs alli\xC3\xA9s restent justes bo\xC3\xAEte ferm\xC3\xA9""e.* Masquer la bo\xC3\xAEte Timers, ou d\xC3\xA9""cocher \"Mes buffs sur alli\xC3\xA9s\", gelait la d\xC3\xA9tection des buffs dispell\xC3\xA9s ou \xC3\xA9""cras\xC3\xA9s -- rouvrir la bo\xC3\xAEte montrait donc des buffs disparus depuis longtemps. Cet entretien tourne maintenant quel que soit l'affichage. Les d\xC3\xA9""comptes alli\xC3\xA9s s'accordent aussi \xC3\xA0 la seconde pr\xC3\xA8s avec vos propres lignes.", CK_FIXED, "Timers", "Timers" },
    { "*Clearer names in the Timers filter.* The buff list mixed single-target and area names (Barstone next to Baraera), \"Gain-\" with one stray \"Boost-\", and 29 \"Indi-\" with a lone \"Geo-\". Each row now carries the family only -- Stone, Water, STR, Regen -- under a header that says which spells it covers. Ticking CHR hides both versions at once.",
      "*Des noms plus clairs dans le filtre Timers.* La liste m\xC3\xA9langeait noms monocibles et de zone (Barstone \xC3\xA0 c\xC3\xB4t\xC3\xA9 de Baraera), des \"Gain-\" avec un \"Boost-\" isol\xC3\xA9, et 29 \"Indi-\" avec un seul \"Geo-\". Chaque ligne ne porte plus que la famille -- Stone, Water, STR, Regen -- sous un en-t\xC3\xAAte qui dit quels sorts elle couvre. Cocher CHR masque les deux versions d'un coup.", CK_IMPROVED, "Timers", "Timers" },
    { "*The minimap drops dead mobs.* A corpse kept its claim colour until it despawned, so a busy camp filled with red dots that never cleared.",
      "*La minimap retire les mobs morts.* Un cadavre gardait sa couleur de claim jusqu'\xC3\xA0 sa disparition, donc un camp charg\xC3\xA9 se remplissait de points rouges qui ne partaient jamais.", CK_FIXED, "Minimap", "Minicarte" },
    { "*A failed save no longer says OK.* If the settings folder is read-only or the disk is full, saving a profile now reports FAILED and keeps it marked unsaved -- before, it announced success and the work was lost at the next load. The updater also stopped offering an \"update\" that would move you BACKWARDS, and a broken layout file can no longer take the plugin down on start-up.",
      "*Une sauvegarde rat\xC3\xA9""e ne dit plus OK.* Si le dossier de r\xC3\xA9glages est en lecture seule ou le disque plein, sauvegarder un profil signale maintenant FAILED et le garde marqu\xC3\xA9 non sauvegard\xC3\xA9 -- avant, il annon\xC3\xA7""ait un succ\xC3\xA8s et le travail \xC3\xA9tait perdu au chargement suivant. L'updater a aussi cess\xC3\xA9 de proposer une \"mise \xC3\xA0 jour\" qui vous ferait RECULER, et un fichier de disposition corrompu ne peut plus faire tomber le plugin au d\xC3\xA9marrage.", CK_FIXED, "Profiles", "Profils" },
    { "*Lighter.* About 2.8 MB of unused artwork left the download, and the Help images are now freed when the plugin unloads instead of piling up over a session.",
      "*Plus l\xC3\xA9ger.* Environ 2,8 Mo d'images inutilis\xC3\xA9""es ont quitt\xC3\xA9 le t\xC3\xA9l\xC3\xA9""chargement, et les visuels d'aide sont maintenant lib\xC3\xA9r\xC3\xA9s au d\xC3\xA9""chargement du plugin au lieu de s'accumuler au fil d'une session.", CK_IMPROVED, "HUD", "HUD" },
};

static const ChangeLine CL_65[] = {
    { "*The Skillchains box now tells nukers which element to burst -- at a glance.* When a chain forms, a \"Nuke:\" line shows the burst element(s) as coloured chips, and every weaponskill in the continuation list carries a coloured square for the element it would produce. A TP gauge at the bottom fills toward 1000 and turns green the moment you can weaponskill.",
      "*La bo\xC3\xAEte Skillchains indique maintenant aux nukeurs quel \xC3\xA9l\xC3\xA9ment burst -- d'un coup d'\xC5\x93il.* Quand une cha\xC3\xAEne se forme, une ligne \"Nuke:\" montre le(s) \xC3\xA9l\xC3\xA9ment(s) de burst en pastilles color\xC3\xA9""es, et chaque weaponskill de la liste de continuation porte un carr\xC3\xA9 color\xC3\xA9 pour l'\xC3\xA9l\xC3\xA9ment qu'il produirait. Une jauge de TP en bas se remplit vers 1000 et passe au vert d\xC3\xA8s que vous pouvez weaponskill.", CK_NEW, "Skillchains", "Skillchains" },
    { "*Sharper timing.* The \"Wait\" now switches to \"Go!\" about half a second early -- a weaponskill you start then still lands in time with normal server lag -- and the closing \"Burst\" countdown is precise now, fading from green through yellow to red as it runs out.",
      "*Timing plus juste.* Le \"Wait\" passe en \"Go!\" environ une demi-seconde plus t\xC3\xB4t -- un weaponskill lanc\xC3\xA9 \xC3\xA0 ce moment atterrit quand m\xC3\xAAme \xC3\xA0 temps avec la latence serveur normale -- et le d\xC3\xA9""compte du \"Burst\" final est d\xC3\xA9sormais pr\xC3\xA9""cis, virant du vert au jaune puis au rouge en s'\xC3\xA9""coulant.", CK_IMPROVED, "Skillchains", "Skillchains" },
    { "*Better skillchain detection.* Scholar Immanence spells are recognised as chain openers and continuers, and Aeonic weapons correctly offer their Radiance / Umbra follow-ups -- but ONLY when you actually wield one, so a non-Aeonic weapon like Ukko's Fury no longer falsely shows Radiance. A Light or Darkness chain also closes correctly now instead of suggesting an impossible next step.",
      "*Meilleure d\xC3\xA9tection des skillchains.* Les sorts d'Immanence du Scholar sont reconnus comme ouvreurs et continuateurs de cha\xC3\xAEne, et les armes Aeonic proposent correctement leurs suites Radiance / Umbra -- mais UNIQUEMENT quand vous en portez une, donc une arme non-Aeonic comme Ukko's Fury n'affiche plus Radiance \xC3\xA0 tort. Une cha\xC3\xAEne Light ou Darkness se ferme aussi correctement au lieu de proposer une \xC3\xA9tape impossible.", CK_IMPROVED, "Skillchains", "Skillchains" },
};
static const ChangeLine CL_64[] = {
    { "*Buffs you cast on your party now keep their timer across a zone.* An area ENHANCING buff that also lands on you -- Protect / Shell / Regen... under Accession -- stays grouped as \"(AoE N)\" with the correct countdown after you zone, instead of breaking into separate per-person rows showing a stale, too-short time. It also no longer briefly flickers to a per-person row while your own buffs reappear after the loading screen. (Songs and rolls drop on a zone, so they don't apply here.)",
      "*Les buffs que vous lancez sur votre groupe gardent leur minuteur en changeant de zone.* Un buff d'AMELIORATION de zone qui vous touche aussi -- Protect / Shell / Regen... sous Accession -- reste regroup\xC3\xA9 en \"(AoE N)\" avec le bon d\xC3\xA9""compte apr\xC3\xA8s un zone, au lieu de se casser en lignes s\xC3\xA9par\xC3\xA9""es par personne avec un temps p\xC3\xA9rim\xC3\xA9 trop court. Il ne clignote plus non plus bri\xC3\xA8vement en ligne par-personne pendant que vos propres buffs r\xC3\xA9""apparaissent apr\xC3\xA8s l'\xC3\xA9""cran de chargement. (Les chants et rolls disparaissent au zone, donc ils ne sont pas concern\xC3\xA9s.)", CK_FIXED, "Timers", "Timers" },
    { "A single-target buff you cast on ONE ally now also keeps a closer time across a zone (its countdown is paused for the loading screen). Note it stays an estimate : the game sends no buff-duration for other players at all -- only for yourself -- so a perfect ally timer is impossible, confirmed by reverse-engineering the client.",
      "Un buff monocible que vous lancez sur UN alli\xC3\xA9 garde aussi un temps plus juste en changeant de zone (son d\xC3\xA9""compte est mis en pause pour l'\xC3\xA9""cran de chargement). \xC3\x80 noter que \xC3\xA7""a reste un estim\xC3\xA9 : le jeu n'envoie aucune dur\xC3\xA9""e de buff pour les autres joueurs -- seulement pour vous -- donc un minuteur d'alli\xC3\xA9 parfait est impossible, confirm\xC3\xA9 en reverse-engineering du client.", CK_IMPROVED, "Timers", "Timers" },
};
static const ChangeLine CL_63[] = {
    { "*You can now show or hide Food, Aftermath, Signet-type and crafting buffs in the Timers box.* Food, the three Aftermath levels, the conquest buffs (Signet / Sanction / Sigil / Ionis) and the synthesis \"Imagery\" buffs each get their own line in the Timers \"Buff filter\" -- with an individual Show/Hide toggle and a whole-group switch. They stay shown by default, so nothing changes until you turn one off.",
      "*Vous pouvez d\xC3\xA9sormais afficher ou masquer les buffs de Nourriture, d'Aftermath, de type Signet et d'Artisanat dans la bo\xC3\xAEte Timers.* La Nourriture, les trois niveaux d'Aftermath, les buffs de conqu\xC3\xAAte (Signet / Sanction / Sigil / Ionis) et les buffs d'atelier (\"Imagery\" de synth\xC3\xA8se) ont chacun leur ligne dans le \"Filtre de buffs\" -- avec un interrupteur Afficher/Masquer individuel et un interrupteur de groupe. Affich\xC3\xA9s par d\xC3\xA9""faut : rien ne change tant que vous n'en coupez pas un.", CK_NEW, "Timers", "Timers" },
    { "Very long area buffs (a San d'Oria Signet lasts 13 hours) now show in the Timers box instead of being dropped, and self-carried buffs like these are no longer hidden by the \"Mine only\" buff-source filter -- their own toggle controls them.",
      "Les buffs de zone tr\xC3\xA8s longs (un Signet de San d'Oria dure 13 heures) s'affichent maintenant dans la bo\xC3\xAEte Timers au lieu d'\xC3\xAAtre ignor\xC3\xA9s, et ces buffs qu'on porte soi-m\xC3\xAAme ne sont plus cach\xC3\xA9s par le filtre de source \"Moi seul\" -- c'est leur propre interrupteur qui les contr\xC3\xB4le.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_62[] = {
    { "*Buffs you cast on your whole party at once now group instantly.* A Protect, Regen or similar spell cast as an area effect -- under Scholar's Accession or Paladin's Majesty -- shows as \"(AoE N)\" right away, instead of briefly listing one party member by name for about a second before grouping.",
      "*Les buffs que vous lancez sur tout votre groupe d'un coup se regroupent instantan\xC3\xA9ment.* Un Protect, Regen ou sort similaire lanc\xC3\xA9 en zone -- sous Accession (\xC3\x89rudit) ou Majesty (Paladin) -- s'affiche directement en \"(AoE N)\", au lieu de lister bri\xC3\xA8vement un membre du groupe par son nom pendant environ une seconde avant de se regrouper.", CK_IMPROVED, "Timers", "Timers" },
};
static const ChangeLine CL_61[] = {
    { "*The Zone Tracker size slider no longer rewrites your settings file while you drag it.* Like every other slider, it now saves once when you let go, instead of about 60 times a second during the drag. Behind the scenes several config controls were also unified -- no change to how they work.",
      "*Le curseur de taille du Zone Tracker ne r\xC3\xA9\xC3\xA9""crit plus votre fichier de r\xC3\xA9glages pendant que vous le glissez.* Comme tous les autres curseurs, il enregistre d\xC3\xA9sormais une seule fois au rel\xC3\xA2""chement, au lieu d'environ 60 fois par seconde pendant le glissement. En coulisses, plusieurs contr\xC3\xB4les de config ont aussi \xC3\xA9t\xC3\xA9 unifi\xC3\xA9s -- sans changement de fonctionnement.", CK_FIXED, "Config", "Config" },
};
static const ChangeLine CL_60[] = {
    { "*More packet guards (continued).* The truncated-packet protection added in 1.0.58 now also covers the PointWatch handlers (XP / CP / Merits / Master Level). Purely defensive : no change to normal behaviour.",
      "*Plus de protections paquets (suite).* La protection contre les paquets tronqu\xC3\xA9s ajout\xC3\xA9""e en 1.0.58 couvre maintenant aussi les handlers PointWatch (XP / CP / M\xC3\xA9rites / Master Level). Purement d\xC3\xA9""fensif : aucun changement en fonctionnement normal.", CK_IMPROVED, "PointWatch", "PointWatch" },
};
static const ChangeLine CL_59[] = {
    { "The gold bullets in the Update and Debug tabs no longer spill outside the list when you scroll -- only the bullet markers were affected (the text was already clipped to the box).",
      "Les puces dor\xC3\xA9""es des onglets Mise \xC3\xA0 jour et Debug ne d\xC3\xA9""bordent plus hors de la liste quand on fait d\xC3\xA9""filer -- seules les puces \xC3\xA9taient concern\xC3\xA9""es (le texte \xC3\xA9tait d\xC3\xA9j\xC3\xA0 clipp\xC3\xA9 \xC3\xA0 la box).", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
};
static const ChangeLine CL_58[] = {
    { "*More guards against malformed packets.* Several Zone Tracker packet handlers (Odyssey / Limbus / Nyzul) now reject a truncated packet instead of reading stale bytes past its real end -- the same length check the rest of the packet handlers already do. Purely defensive : no change to normal behaviour.",
      "*Plus de protections contre les paquets malform\xC3\xA9s.* Plusieurs handlers de paquets du Zone Tracker (Odyssey / Limbus / Nyzul) rejettent d\xC3\xA9sormais un paquet tronqu\xC3\xA9 au lieu de lire des octets p\xC3\xA9rim\xC3\xA9s au-del\xC3\xA0 de sa fin -- le m\xC3\xAAme contr\xC3\xB4le de longueur que font d\xC3\xA9j\xC3\xA0 les autres handlers. Purement d\xC3\xA9""fensif : aucun changement en fonctionnement normal.", CK_IMPROVED, "Zone Tracker", "Zone Tracker" },
};
static const ChangeLine CL_57[] = {
    { "*Each box can now use its OWN FFXI window skin, independent of the party.* Set a box (Timers, Hate List, Debuffs, ...) to Custom -> FFXI and pick any of the game skins in the grid -- it no longer has to match the party's skin, and it works even when the party is on a procedural theme. (Before, every FFXI box was forced to show the party's skin, and could not use FFXI at all unless the party did too.)",
      "*Chaque bo\xC3\xAEte peut d\xC3\xA9sormais utiliser son PROPRE skin de fen\xC3\xAAtre FFXI, ind\xC3\xA9pendamment de la party.* Mets une bo\xC3\xAEte (Timers, Hate List, Debuffs...) en Custom -> FFXI et choisis n'importe quel skin du jeu dans la grille -- il n'est plus oblige de suivre le skin de la party, et \xC3\xA7""a marche m\xC3\xAAme quand la party est sur un th\xC3\xA8me proc\xC3\xA9""dural. (Avant, toute bo\xC3\xAEte FFXI \xC3\xA9tait forc\xC3\xA9""e d'afficher le skin de la party, et ne pouvait m\xC3\xAAme pas \xC3\xAAtre en FFXI si la party ne l'\xC3\xA9tait pas.)", CK_NEW, "HUD", "HUD" },
};
static const ChangeLine CL_56[] = {
    { "*Your HUD layout can no longer be corrupted by a crash while it saves.* The edit-mode layout file is now written to a temporary copy and swapped in atomically, so a crash mid-save can never leave it half-written or empty.",
      "*Ta disposition HUD ne peut plus \xC3\xAAtre corrompue par un crash pendant sa sauvegarde.* Le fichier de disposition (mode \xC3\xA9""dition) est d\xC3\xA9sormais \xC3\xA9""crit dans une copie temporaire puis \xC3\xA9""chang\xC3\xA9 de fa\xC3\xA7on atomique, donc un crash en pleine sauvegarde ne peut plus le laisser \xC3\xA0 moiti\xC3\xA9 \xC3\xA9""crit ou vide.", CK_FIXED, "Edit Layout", "\xC3\x89""diter dispo" },
    { "*Config-page preview icons no longer go missing for the rest of the session.* The Timers, Zone Tracker, Debuffs and Treasure preview panels gave up loading their icons after a single badly-timed miss; they now retry, like the rest of the HUD already did.",
      "*Les ic\xC3\xB4nes d'aper\xC3\xA7u de la page Config ne disparaissent plus pour le reste de la session.* Les aper\xC3\xA7us Timers, Zone Tracker, Debuffs et Treasure abandonnaient le chargement de leurs ic\xC3\xB4nes apr\xC3\xA8s un seul \xC3\xA9""chec mal tomb\xC3\xA9 ; ils r\xC3\xA9""essaient maintenant, comme le reste du HUD le faisait d\xC3\xA9j\xC3\xA0.", CK_FIXED, "Config", "Config" },
};
static const ChangeLine CL_55[] = {
    { "*Area song counts are more accurate when you re-sing.* If a party member is out of range when you re-cast, their older song is now listed by name (\"Aeryn - Victory March\") on its own timer, instead of being hidden inside the \"(AoE N)\" count as if they were still fully buffed. A song still on an ally but no longer on you (pushed off by newer songs) also stops showing a false \"(AoE 2)\".",
      "*Les comptes de chants de zone sont plus pr\xC3\xA9""cis quand tu rechantes.* Si un membre est hors de portee au moment o\xC3\xB9 tu relances, son ancien chant est d\xC3\xA9sormais liste par nom (\"Aeryn - Victory March\") sur son propre minuteur, au lieu d'\xC3\xAAtre cach\xC3\xA9 dans le compte \"(AoE N)\" comme s'il \xC3\xA9tait encore pleinement buff\xC3\xA9. Un chant encore sur un alli\xC3\xA9 mais plus sur toi (pouss\xC3\xA9 dehors par de nouveaux chants) n'affiche plus non plus un faux \"(AoE 2)\".", CK_IMPROVED, "Timers", "Timers" },
    { "*A song you replace on purpose no longer flashes a false \"OUT\" alert.* When you Pianissimo a song onto a party member and it pushes one of their songs out of a slot, that swap is now silent instead of blinking a red \"OUT\" as if you had lost it.",
      "*Un chant que tu remplaces expr\xC3\xA8s ne clignote plus une fausse alerte \"OUT\".* Quand tu Pianissimo un chant sur un membre et qu'il en pousse un autre hors slot, cet \xC3\xA9""change est d\xC3\xA9sormais silencieux au lieu de clignoter un \"OUT\" rouge comme si tu l'avais perdu.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_54[] = {
    { "*The duration shown for a Regen you cast on a party member is now correct.* It was reading too short : gear that specifically lengthens Regen (a staff, certain armor pieces) was not being counted -- unlike other enhancing spells, Regen has its own duration-boosting gear. AioHUD now reads that straight from the game's item data, so it is right for any set.",
      "*La dur\xC3\xA9""e affich\xC3\xA9""e pour un Regen que tu poses sur un membre de la party est d\xC3\xA9sormais correcte.* Elle \xC3\xA9tait trop courte : l'\xC3\xA9quipement qui allonge sp\xC3\xA9""cifiquement le Regen (un b\xC3\xA2ton, certaines pi\xC3\xA8""ces) n'\xC3\xA9tait pas compt\xC3\xA9 -- contrairement aux autres sorts d'enhancing, le Regen a son propre gear de dur\xC3\xA9""e. AioHUD le lit maintenant directement dans les donn\xC3\xA9""es d'items du jeu, donc c'est juste pour n'importe quel set.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_53[] = {
    { "*Bard song timers are more accurate.* A song now shows its own remaining time (Victory March no longer borrows Honor March's), two songs of the same name no longer share one timer, and area songs on your party regroup correctly when you re-sing one -- and now survive a plugin reload or a zone change.",
      "*Les minuteurs de chants du barde sont plus pr\xC3\xA9""cis.* Un chant affiche d\xC3\xA9sormais son propre temps restant (Victory March n'emprunte plus celui d'Honor March), deux chants de m\xC3\xAAme nom ne partagent plus un minuteur, et les chants de zone sur ta party se regroupent correctement quand tu en rechantes un -- et survivent maintenant \xC3\xA0 un rechargement du plugin ou \xC3\xA0 un changement de zone.", CK_IMPROVED, "Timers", "Timers" },
    { "*Songs you put on a party member no longer show a false \"OUT\" alert once that member leaves your zone.* When you change zones (or they do), those song rows are cleaned up instead of lingering in red as if you had lost them.",
      "*Les chants que tu poses sur un membre de la party n'affichent plus une fausse alerte \"OUT\" une fois ce membre hors de ta zone.* Quand tu changes de zone (ou lui), ces lignes de chant sont nettoy\xC3\xA9""es au lieu de rester en rouge comme si tu les avais perdus.", CK_FIXED, "Timers", "Timers" },
    { "*The Timers list is grouped more logically :* your own buffs first, then the buffs you cast on allies, then buffs other players cast on you, then trusts last.",
      "*La liste des Timers est regroup\xC3\xA9""e plus logiquement :* d'abord tes propres buffs, puis les buffs que tu poses sur tes alli\xC3\xA9s, puis ceux que d'autres joueurs te posent, et les trusts en dernier.", CK_IMPROVED, "Timers", "Timers" },
};
static const ChangeLine CL_52[] = {
    { "*The colour picker is redesigned and better proportioned.* A real square saturation/value box on top, a full-width hue slider below it, and a larger preset grid -- laid out as a compact card instead of one strip stretched across the whole panel. Applies to every colour in every module.",
      "*Le s\xC3\xA9lecteur de couleur est repens\xC3\xA9 et mieux proportionn\xC3\xA9.* Un vrai carr\xC3\xA9 saturation/valeur en haut, un slider de teinte en dessous, et une grille de presets plus grande -- en carte compacte au lieu d'une bande \xC3\xA9tir\xC3\xA9""e sur toute la largeur. S'applique \xC3\xA0 chaque couleur de chaque module.", CK_IMPROVED, "Config", "Config" },
    { "*Favourite colours.* Build your own palette right in the colour picker : the *+* button saves the current colour, a click on a saved swatch reuses it, and hovering one shows a small *x* to remove it. Shared by every picker and kept across sessions.",
      "*Couleurs favorites.* Compose ta propre palette dans le s\xC3\xA9lecteur : le bouton *+* enregistre la couleur actuelle, un clic sur un favori la r\xC3\xA9""applique, et le survol affiche un petit *x* pour l'enlever. Partag\xC3\xA9""e par tous les s\xC3\xA9lecteurs et conserv\xC3\xA9""e d'une session \xC3\xA0 l'autre.", CK_NEW, "Config", "Config" },
    { "In Arcade WS, the three colour pickers (Name / Damage A / Damage B) no longer interfere with each other -- dragging one used to move the others.",
      "Dans Arcade WS, les trois s\xC3\xA9lecteurs de couleur (Nom / D\xC3\xA9g\xC3\xA2ts A / D\xC3\xA9g\xC3\xA2ts B) n'interf\xC3\xA8rent plus entre eux -- d\xC3\xA9placer l'un bougeait les autres.", CK_FIXED, "Arcade WS", "Arcade WS" },
};
static const ChangeLine CL_51[] = {
    { "*The Timers buff-filter alerts are clearer and warn you earlier.* The four states are now *Show / Show+alert / Hide / Hide+alert* (the old \"focus\" wording is gone), and a *+alert* buff now BLINKS its name and timer the moment it drops under the *Alert under* time -- an early \"recast soon\" cue, not just the last-10-seconds flash. The two sliders are *Alert under* and *Alert duration*.",
      "*Les alertes du filtre de buffs sont plus claires et te pr\xC3\xA9viennent plus t\xC3\xB4t.* Les quatre \xC3\xA9tats sont maintenant *Afficher / Afficher+alerte / Masquer / Masquer+alerte* (le mot \"focus\" dispara\xC3\xAEt), et un buff *+alerte* CLIGNOTE d\xC3\xA9sormais son nom et son minuteur d\xC3\xA8s qu'il passe sous le temps *Alerter sous* -- un avertissement \"recast bient\xC3\xB4t\", pas seulement le clignotement des 10 derni\xC3\xA8res secondes. Les deux curseurs sont *Alerter sous* et *Dur\xC3\xA9""e de l'alerte*.", CK_IMPROVED, "Timers", "Timers" },
    { "*A buff someone re-casts over yours now shows the right caster and timer.* When an ally or a trust overwrites your Protect / Shell -- or a weaker spell is refused with \"no effect\" (e.g. a lower Phalanx over your Phalanx II) -- the row no longer keeps the old name and owner while only the time updates. Covers the Majesty AoE case too : your own copy stops folding into the \"(AoE N)\" group once someone re-casts it on you.",
      "*Un buff qu'on relance par-dessus le tien affiche le bon lanceur et le bon temps.* Quand un alli\xC3\xA9 ou un trust \xC3\xA9""crase ton Protect / Shell -- ou qu'un sort plus faible est refus\xC3\xA9 en \"no effect\" (ex. un Phalanx inf\xC3\xA9rieur sur ton Phalanx II) -- la ligne ne garde plus l'ancien nom et propri\xC3\xA9taire avec juste le temps qui change. Couvre aussi le cas Majesty AoE : ta propre copie ne se replie plus dans le groupe \"(AoE N)\" une fois qu'on te la relance.", CK_FIXED, "Timers", "Timers" },
    { "The minimap and its markers could stop loading -- a black map on every zone-in -- after the PC had been running for about 25 days. They load again.",
      "La minicarte et ses marqueurs pouvaient cesser de se charger -- carte noire \xC3\xA0 chaque changement de zone -- apr\xC3\xA8s environ 25 jours d'allumage du PC. Ils se rechargent.", CK_FIXED, "Minimap", "Minicarte" },
    { "The in-game Help was refreshed to match the current modules : Timers rewritten for the family filter, plus several stale control names and two wrong descriptions (Treasure Pool's index and timer colours, PointWatch) corrected.",
      "L'Aide en jeu a \xC3\xA9t\xC3\xA9 mise \xC3\xA0 jour pour coller aux modules actuels : Timers r\xC3\xA9\xC3\xA9""crit pour le filtre par famille, plus plusieurs noms de contr\xC3\xB4les p\xC3\xA9rim\xC3\xA9s et deux descriptions fausses (l'index et les couleurs du Pool de tr\xC3\xA9sor, PointWatch) corrig\xC3\xA9s.", CK_IMPROVED, "Config", "Config" },
};
static const ChangeLine CL_50[] = {
    { "*Timers has a new buff filter, organised by family.* The old per-job track list is gone -- buffs are grouped by magic family (Protect/Shell, Haste, Barspells, Songs, Rolls, Ninjutsu...) and Job Abilities are listed by job with your current job in gold. Each buff has ONE setting shared across all your jobs (Show / Show+alert / Hide / Hide+alert), so hiding e.g. Shell hides it on every job. Recasts are always shown.",
      "*Timers a un nouveau filtre de buffs, rang\xC3\xA9 par famille.* L'ancienne liste 'suivi par job' dispara\xC3\xAEt -- les buffs sont group\xC3\xA9s par famille de magie (Protect/Shell, Haste, Barspells, Chants, Rolls, Ninjutsu...) et les capacit\xC3\xA9s de job sont list\xC3\xA9""es par job, ton job actuel en dor\xC3\xA9. Chaque buff a UN seul r\xC3\xA9glage partag\xC3\xA9 entre tous tes jobs (Afficher / Afficher+alerte / Masquer / Masquer+alerte), donc masquer par ex. Shell le masque sur tous tes jobs. Les recast sont toujours affich\xC3\xA9s.", CK_NEW, "Timers", "Timers" },
    { "*The buff-source filter now handles another player's trusts and their mixes.* On a second character in your party (your mule, while your main's trusts are out), a trust's buffs are correctly seen as trust-cast, so 'me only' / 'me + players' hide them. In particular a Trust's stat-boost mix (STR/DEX/VIT... Boost from Monberaux/Ygnas) no longer counts as your own -- only a Gain-X you actually cast stays.",
      "*Le filtre de source des buffs g\xC3\xA8re maintenant les trusts d'un autre joueur et leurs mix.* Sur un second personnage dans ta party (ton mule, pendant que les trusts de ton main sont sortis), les buffs d'un trust sont bien vus comme lanc\xC3\xA9s par un trust, donc 'moi seulement' / 'moi + joueurs' les cachent. En particulier le mix de boost de stats d'un trust (STR/DEX/VIT... Boost de Monberaux/Ygnas) ne compte plus comme le tien -- seul un Gain-X que tu as r\xC3\xA9""ellement lanc\xC3\xA9 reste.", CK_IMPROVED, "Timers", "Timers" },
    { "A song sung by someone else no longer wears a previous singer's job-ability tag (e.g. Ulmia's Madrigal showing \"NT\").",
      "Un chant chant\xC3\xA9 par quelqu'un d'autre ne porte plus le tag de capacit\xC3\xA9 d'un chanteur pr\xC3\xA9""c\xC3\xA9""dent (par ex. le Madrigal d'Ulmia affiche \"NT\").", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_49[] = {
    { "*Minimap dots no longer spill past the frame.* Party, NPC and monster markers are now cut cleanly at the map's edge instead of poking outside it just before they vanish -- on the round map and the square one, with or without a border.",
      "*Les points du minimap ne d\xC3\xA9""bordent plus du cadre.* Les marqueurs de joueurs, PNJ et monstres sont d\xC3\xA9sormais coup\xC3\xA9s net au bord de la carte au lieu de d\xC3\xA9passer juste avant de dispara\xC3\xAEtre -- en carte ronde comme carr\xC3\xA9""e, avec ou sans bordure.", CK_FIXED, "Minimap", "Minicarte" },
    { "*The Vana'diel clock now fits its text in French.* The long day names (\"Jour de Lumiere\") no longer run under the frame, and the clock keeps the same centred margins whether it sits above, below, left or right of the map (left / right now hug the map with a clean gap).",
      "*L'horloge de Vana'diel s'adapte au texte fran\xC3\xA7""ais.* Les noms de jour longs (\"Jour de Lumi\xC3\xA8re\") ne passent plus sous le cadre, et l'horloge garde les m\xC3\xAAmes marges centr\xC3\xA9""es qu'elle soit en haut, en bas, \xC3\xA0 gauche ou \xC3\xA0 droite de la carte (gauche / droite collent proprement \xC3\xA0 la carte).", CK_FIXED, "Minimap", "Minicarte" },
    { "*Point Watch no longer shifts when you switch XP, CP or ML.* The three modes share one layout now -- the box keeps the same size and the numbers stay aligned across modes -- and the live preview plus the edit-mode box show the mode you actually picked.",
      "*Point Watch ne bouge plus quand on passe de XP \xC3\xA0 CP ou ML.* Les trois modes partagent une m\xC3\xAAme disposition -- la bo\xC3\xAEte garde la m\xC3\xAAme taille et les nombres restent alignes d'un mode \xC3\xA0 l'autre -- et l'aper\xC3\xA7u live comme la bo\xC3\xAEte en mode \xC3\xA9""dition affichent le mode r\xC3\xA9""ellement choisi.", CK_FIXED, "PointWatch", "PointWatch" },
    { "*Keep-out zones can be resized one side at a time.* In the Rules editor, a selected zone now has a handle in the middle of each side (on top of the corner handles), so you can stretch just the width or just the height without changing the other.",
      "*Les zones interdites se redimensionnent c\xC3\xB4t\xC3\xA9 par c\xC3\xB4t\xC3\xA9.* Dans l'\xC3\xA9""diteur Rules, une zone s\xC3\xA9lectionn\xC3\xA9""e a maintenant une poign\xC3\xA9""e au milieu de chaque c\xC3\xB4t\xC3\xA9 (en plus des coins), pour \xC3\xA9tirer seulement la largeur ou seulement la hauteur sans changer l'autre.", CK_NEW, "Edit Layout", "\xC3\x89""diter dispo" },
    { "In the party-buffs preview, the \"+N\" more-buffs marker is no longer glued to the last icon.",
      "Dans l'aper\xC3\xA7u des buffs de groupe, l'indicateur \"+N\" (buffs suppl\xC3\xA9mentaires) n'est plus coll\xC3\xA9 \xC3\xA0 la derni\xC3\xA8re ic\xC3\xB4ne.", CK_FIXED, "Party", "Groupe" },
};

// One entry per released version, NEWEST FIRST. The Update tab renders each as a collapsible header ; the newest
// (index 0) starts expanded, the rest collapsed (relOpen_ in config_page.h defaults index 0 = true).
struct Release { const char* version; const ChangeLine* lines; int n; const char* date = nullptr; };   // date : "YYYY-MM-DD", the release tag's
static const ChangeLine CL_80[] = {
    { "*The whole config menu has depth now.* Cards, buttons, chips, section bars and the module list all sit on one elevation scale -- a raised control is lighter than the surface under it, not darker -- and they cast real shadows. Every raised thing shares the same steel edging and the same light along its top edge, tinted by YOUR accent colour instead of a fixed grey.",
      "*Tout le menu de config a de la profondeur.* Cartes, boutons, puces, barres de section et liste des modules suivent une m\xC3\xAAme \xC3\xA9""chelle d'\xC3\xA9l\xC3\xA9vation -- un contr\xC3\xB4le en relief est plus clair que la surface qui le porte, non plus sombre -- et projettent de vraies ombres. Chaque \xC3\xA9l\xC3\xA9ment en relief partage le m\xC3\xAAme liser\xC3\xA9 acier et la m\xC3\xAAme lumi\xC3\xA8re sur son bord haut, teint\xC3\xA9""e par TA couleur d'accent au lieu d'un gris fixe.", CK_IMPROVED, "Config", "Config" },
    { "*Rounded corners are exact.* Every corner is drawn from a baked coverage mask at one texel per pixel instead of an approximated polygon, so tabs, cards, chips and swatches are crisp at rest and stay crisp while a section folds.",
      "*Les arrondis sont exacts.* Chaque coin est dessin\xC3\xA9 depuis un masque de couverture cuit, un texel par pixel, au lieu d'un polygone approche : onglets, cartes, puces et pastilles sont nets au repos et le restent pendant qu'une section se d\xC3\xA9plie.", CK_IMPROVED, "Config", "Config" },
    { "*The colour picker is a single card.* A saturation/value square with a vertical hue strip beside it, the colour itself shown large with its hex written on it, your favourites in the column next to them, and underneath a real shade chart -- twelve hues by light / base / deep, plus white, grey and near-black. Its height no longer changes when you save a favourite.",
      "*Le s\xC3\xA9lecteur de couleur est une seule carte.* Un carr\xC3\xA9 saturation/valeur avec la bande de teinte verticale \xC3\xA0 c\xC3\xB4t\xC3\xA9, la couleur affich\xC3\xA9""e en grand avec son hex \xC3\xA9""crit dessus, tes favoris dans la colonne voisine, et en dessous un vrai nuancier -- douze teintes en clair / base / fonc\xC3\xA9, plus blanc, gris et quasi-noir. Sa hauteur ne bouge plus quand tu enregistr\xC3\xA9s un favori.", CK_IMPROVED, "Config", "Config" },
    { "*A custom accent colour is no longer washed out.* Picking a vivid red used to apply a pale pink : the colour was mixed toward white to guarantee legibility, which removes saturation. A vivid pick now comes through exactly as chosen, and only genuinely dark colours are lifted -- by brightness, not by bleaching.",
      "*Une couleur d'accent personnalis\xC3\xA9""e n'est plus d\xC3\xA9lav\xC3\xA9""e.* Choisir un rouge vif appliquait un rose p\xC3\xA2le : la couleur \xC3\xA9tait m\xC3\xA9lang\xC3\xA9""e vers le blanc pour garantir la lisibilit\xC3\xA9, ce qui retire la saturation. Un choix vif passe d\xC3\xA9sormais exactement tel quel, et seules les couleurs vraiment sombres sont relev\xC3\xA9""es -- en luminosit\xC3\xA9, pas en blanchiment.", CK_FIXED, "Config", "Config" },
    { "*Every module's menu follows one logic.* Sections hold ONE subject each and typography is always last. Timers is split into Display / Content / Rows, Zone Tracker into Display / Content, Target's standalone debuff list gets its own section instead of hiding at the bottom of the debuff-icon settings, and Party / Alliance separate the box from what a member row carries.",
      "*Les menus de chaque module suivent une seule logique.* Une section = un sujet, et la typographie est toujours en dernier. Timers est d\xC3\xA9""coup\xC3\xA9 en Affichage / Contenu / Lignes, Zone Tracker en Affichage / Contenu, la liste de debuffs autonome de Target a sa propre section au lieu d'\xC3\xAAtre au fond des r\xC3\xA9glages d'ic\xC3\xB4nes, et Party / Alliance s\xC3\xA9parent la bo\xC3\xAEte de ce que porte une ligne de membre.", CK_IMPROVED, "Config", "Config" },
    { "*You choose how each column is ordered.* Duration can group by person then by time (as before) or simply put the shortest first, everyone mixed -- trusts stay last either way. Recast can be shortest-first or alphabetical.",
      "*Tu choisis l'ordre de chaque colonne.* Dur\xC3\xA9""e peut grouper par personne puis par temps (comme avant) ou simplement mettre le plus court en premier, tout le monde m\xC3\xA9lang\xC3\xA9 -- les trusts restent derniers dans les deux cas. Recast peut \xC3\xAAtre au plus court ou par ordre alphab\xC3\xA9tique.", CK_NEW, "Timers", "Timers" },
    { "*Take back a buff you cast on the wrong person.* Cast Haste on the wrong name and AioHUD would keep expecting that person to have it, and say so in red when it ran out. Watched rows now carry a small number on their left ; */aio out <number>* removes that line. The number is fixed for as long as the row exists, and casting the spell on that person again later starts watching it properly.",
      "*Annule un buff lanc\xC3\xA9 sur la mauvaise personne.* Un Haste sur le mauvais nom et AioHUD attendait ce buff sur cette personne pour toujours, et le signalait en rouge une fois expir\xC3\xA9. Les lignes suivies portent maintenant un petit num\xC3\xA9ro \xC3\xA0 gauche ; */aio out <num\xC3\xA9ro>* retire la ligne. Le num\xC3\xA9ro ne change pas tant que la ligne existe, et relancer le sort sur cette personne plus tard remet le suivi en place.", CK_NEW, "Timers", "Timers" },
    { "*The buff-strip editor has two states instead of three.* A tile is on, or off with the red slash -- the half-lit \"in the catalogue but not seen yet\" state is gone. A disabled tile keeps its name fully readable, because this editor is the only place to switch it back on.",
      "*L'\xC3\xA9""diteur de bandeau de buffs a deux \xC3\xA9tats au lieu de trois.* Une tuile est allum\xC3\xA9""e, ou \xC3\xA9teinte avec le trait rouge -- l'\xC3\xA9tat \xC3\xA0 demi-\xC3\xA9teint \"dans le catalogue mais jamais vu\" dispara\xC3\xAEt. Une tuile d\xC3\xA9sactiv\xC3\xA9""e garde son nom parfaitement lisible, puisque cet \xC3\xA9""diteur est le seul endroit pour la r\xC3\xA9""activer.", CK_IMPROVED, "Party", "Groupe" },
    { "Dragging in a colour picker no longer stops the moment the pointer leaves the settings column -- the drag now holds until you release the button.",
      "Un glisser dans un s\xC3\xA9lecteur de couleur ne s'arr\xC3\xAAte plus d\xC3\xA8s que le pointeur quitte la colonne de r\xC3\xA9glages -- le glisser tient jusqu'au rel\xC3\xA2""chement du bouton.", CK_FIXED, "Config", "Config" },
    { "Button labels stay readable on any accent colour (dark text on a bright button, light text on a dark one), textured elements now fade in with the menu instead of appearing at once, and the French \"Boite cout\" label in Party is no longer mangled.",
      "Les libell\xC3\xA9s de boutons restent lisibles sur n'importe quelle couleur d'accent (texte sombre sur bouton clair, texte clair sur bouton sombre), les \xC3\xA9l\xC3\xA9ments textures apparaissent maintenant en fondu avec le menu au lieu de surgir d'un coup, et le libell\xC3\xA9 \"Bo\xC3\xAEte co\xC3\xBBt\" de Party n'est plus corrompu.", CK_FIXED, "Config", "Config" },
};

static const ChangeLine CL_87[] = {
    { "*A buff row no longer claims to be an area spell when it was not.* Haste or Phalanx cast on three people one at a time was folded into a single \"(AoE 3)\" line -- a claim about what the cast did, made by three casts that each hit one person. That came from a setting, and the setting was ON by default, so it was the normal behaviour for anyone who had never gone looking for it. It is gone: a row groups only when the spell really did reach several people -- a song, Protectra, a Corsair roll, or a spell made area-wide by Scholar's Accession or Manifestation. Everything else is listed one row per person, which is also the only form that can tell you WHO is missing one.",
      "*Une ligne de buff ne pr\xC3\xA9tend plus \xC3\xAAtre un sort de zone quand elle ne l'est pas.* Un Haste ou un Phalanx lanc\xC3\xA9 sur trois personnes une par une \xC3\xA9tait repli\xC3\xA9 en une seule ligne \"(AoE 3)\" -- une affirmation sur ce qu'a fait le cast, produite par trois casts qui ont touch\xC3\xA9 une personne chacun. Cela venait d'un r\xC3\xA9glage, et ce r\xC3\xA9glage \xC3\xA9tait ACTIVE par d\xC3\xA9""faut : c'\xC3\xA9tait donc le comportement normal pour quiconque n'\xC3\xA9tait jamais all\xC3\xA9 le chercher. Il est supprim\xC3\xA9 : une ligne ne se groupe que si le sort a r\xC3\xA9""ellement atteint plusieurs personnes -- une song, un Protectra, un roll de Corsaire, ou un sort pass\xC3\xA9 en zone par Accession ou Manifestation de Scholar. Tout le reste est liste une ligne par personne, la seule forme qui peut aussi te dire QUI n'en a pas.", CK_FIXED, "Timers", "Timers" },
    { "*Zoning no longer throws away the buffs you put on your party.* The Haste, the Refresh and the Phalanx you had just spread over everyone vanished from the box on a zone change and could only come back by casting them again -- while in the game they were still running. Only the songs are forgotten on a zone now, and that on purpose: a song is re-sung in six seconds, and its rows were scattering while the game re-sent the party's buffs piece by piece.",
      "*Changer de zone ne jette plus les buffs que tu as pos\xC3\xA9s sur ton groupe.* Le Haste, le Refresh et le Phalanx que tu venais d'\xC3\xA9taler sur tout le monde disparaissaient de la bo\xC3\xAEte au changement de zone et ne revenaient qu'en les relan\xC3\xA7""ant -- alors que dans le jeu ils tournaient toujours. Seules les songs sont d\xC3\xA9sormais oubli\xC3\xA9""es en zonant, et c'est volontaire : une song se re-chante en six secondes, et ses lignes s'\xC3\xA9parpillaient pendant que le jeu renvoyait les buffs du groupe morceau par morceau.", CK_FIXED, "Timers", "Timers" },
};

static const ChangeLine CL_86[] = {
    { "*A weaker Dia no longer replaces a stronger one.* Cast Dia III, then Dia II on the same target, and the row became Dia II with its shorter timer -- the game keeps the Dia III. It was not an obvious one to see: the game answers a refused Dia the way it answers one that worked, with its damage, and says nothing at all about the effect, so this is now worked out rather than waited for. Same for Bio, and for the Scholar Helix spells, where a tier I used to take over a tier II you had just burst with.",
      "*Un Dia plus faible ne remplace plus un Dia plus fort.* Lance Dia III, puis Dia II sur la m\xC3\xAAme cible, et la ligne passait \xC3\xA0 Dia II avec son timer plus court -- alors que le jeu garde le Dia III. Ce n'\xC3\xA9tait pas simple \xC3\xA0 voir : le jeu r\xC3\xA9pond \xC3\xA0 un Dia refus\xC3\xA9 exactement comme \xC3\xA0 un Dia qui a pris, avec ses d\xC3\xA9g\xC3\xA2ts, et ne dit rien de l'effet. C'est donc d\xC3\xA9""duit d\xC3\xA9sormais, au lieu d'\xC3\xAAtre attendu. Pareil pour Bio, et pour les Helix de Scholar, ou un tier I reprenait la place d'un tier II fra\xC3\xAE""chement pos\xC3\xA9 pour le burst.", CK_FIXED, "Debuffs", "Debuffs" },
    { "*Your debuff timers learn their real duration, spell by spell.* The game announces the end of a debuff YOU cast, so the plugin now times it -- which means your merits, your job points and your gear are already in the number, with nothing to configure. Until now that measurement was filed by status instead of by spell, and all five Dia tiers share one status: a single Dia III running out taught the plugin that a Dia lasts 180 seconds, and every Dia I after that counted down from 180 instead of 60.",
      "*Tes minuteurs de debuffs apprennent leur vraie dur\xC3\xA9""e, sort par sort.* Le jeu annonce la fin d'un debuff que TU as pos\xC3\xA9, donc le plugin le chronom\xC3\xA8tre -- tes m\xC3\xA9rites, tes job points et ton \xC3\xA9quipement sont donc d\xC3\xA9j\xC3\xA0 dans le chiffre, sans rien \xC3\xA0 r\xC3\xA9gler. Jusqu'ici cette mesure \xC3\xA9tait rang\xC3\xA9""e par statut et non par sort, et les cinq tiers de Dia partagent un seul statut : un Dia III arrive \xC3\xA0 expiration apprenait au plugin qu'un Dia dure 180 secondes, et chaque Dia I suivant d\xC3\xA9""comptait depuis 180 au lieu de 60.", CK_IMPROVED, "Debuffs", "Debuffs" },
    { "*A spell absorbed by a shadow, or never cast at all, no longer leaves a debuff behind.* Two cases were being recorded as if they had landed: a spell eaten by the target's Utsusemi shadows, and a cast interrupted because you were paralyzed. Each left a phantom debuff on the monster, counting down on nothing.",
      "*Un sort absorbe par une ombre, ou jamais lanc\xC3\xA9, ne laisse plus de debuff derri\xC3\xA8re lui.* Deux cas \xC3\xA9taient enregistr\xC3\xA9s comme s'ils avaient pris : un sort aval\xC3\xA9 par les ombres Utsusemi de la cible, et un lancement interrompu parce que tu \xC3\xA9tais paralys\xC3\xA9. Chacun laissait un debuff fant\xC3\xB4me sur le monstre, \xC3\xA0 d\xC3\xA9""compter dans le vide.", CK_FIXED, "Debuffs", "Debuffs" },
    { "*Dynamis - Divergence is no longer shown as ordinary Dynamis.* It was drawing the Dynamis window -- the five granules of time, which do not exist there, and a sixty-minute countdown that ignored every extension. It now has its own box, and its clock is the game's own: the countdown you see is the one the server keeps, statue and boss extensions included.",
      "*Dynamis - Divergence n'est plus affich\xC3\xA9 comme le Dynamis ordinaire.* La bo\xC3\xAEte de Dynamis s'affichait -- les cinq granules de temps, qui n'existent pas l\xC3\xA0-bas, et un d\xC3\xA9""compte de soixante minutes qui ignorait toutes les extensions. Elle a maintenant sa propre bo\xC3\xAEte, et son horloge est celle du jeu : le d\xC3\xA9""compte affich\xC3\xA9 est celui que tient le serveur, extensions de statues et de boss comprises.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
    { "Housekeeping you will never see: a release can no longer be built with a missing or truncated icon sheet -- the packaging compares what it is about to ship against the source, file by file, and refuses. And a run left in the cache that could not possibly still be going is no longer restored when the plugin reloads, which is what made a timer show a number climbing instead of falling.",
      "Rangement que tu ne verras jamais : une release ne peut plus \xC3\xAAtre construite avec une planche d'ic\xC3\xB4nes manquante ou tronqu\xC3\xA9""e -- l'empaquetage compare fichier par fichier ce qu'il s'appr\xC3\xAAte \xC3\xA0 livrer avec la source, et refuse. Et une run rest\xC3\xA9""e en cache qui ne peut plus \xC3\xAAtre en cours n'est plus restaur\xC3\xA9""e au rechargement du plugin, ce qui faisait afficher \xC3\xA0 un minuteur un nombre qui montait au lieu de descendre.", CK_IMPROVED, "HUD", "HUD" },
};

static const ChangeLine CL_85[] = {
    { "*The spell cost box and the selection cursor stop blinking out while you idle.* The last version taught AioHUD to refuse an address that merely looks like a menu -- and the test was too harsh. The correct address shows the same placeholder name for as long as the chat input holds the focus, so simply not opening a menu for a second was taken as proof it was wrong : the box died, came back, and died again. An address proven by a real menu name is now final, and an unproven one stays in service while the search runs underneath it, so there is no longer an instant where nothing is connected.",
      "*La bo\xC3\xAEte de co\xC3\xBBt des sorts et le curseur de s\xC3\xA9lection ne clignotent plus quand tu ne fais rien.* La version pr\xC3\xA9""c\xC3\xA9""dente a appris \xC3\xA0 AioHUD \xC3\xA0 refuser une adresse qui a seulement l'air d'\xC3\xAAtre un menu -- et le test \xC3\xA9tait trop dur. La bonne adresse affiche le m\xC3\xAAme nom de remplissage tant que la saisie du chat a le focus : ne pas ouvrir de menu pendant une seconde valait donc preuve qu'elle \xC3\xA9tait fausse, et la bo\xC3\xAEte mourait, revenait, remourait. Une adresse prouv\xC3\xA9""e par un vrai nom de menu est d\xC3\xA9sormais d\xC3\xA9""finitive, et une adresse non prouv\xC3\xA9""e reste en service pendant que la recherche tourne dessous -- il n'y a plus d'instant o\xC3\xB9 rien n'est branche.", CK_FIXED, "Party", "Groupe" },
    { "*AioHUD no longer writes a bug report about a problem you do not have.* Logging in and leaving the chat open for ninety seconds was enough to produce a report accusing a perfectly healthy client : the check counted the chat input as an open menu, so the accusation was guaranteed rather than earned. It is removed, not tuned -- a check that fires wrongly buries the ones that do not. Any aiohud_bugreport file dated 11 September can be thrown away. The log no longer calls an address \"unproven\" while it is working, either.",
      "*AioHUD n'\xC3\xA9""crit plus de rapport de bug sur un probl\xC3\xA8me que tu n'as pas.* Se connecter et laisser le chat ouvert quatre-vingt-dix secondes suffisait \xC3\xA0 produire un rapport accusant un client parfaitement sain : la v\xC3\xA9rification comptait la saisie du chat comme un menu ouvert, donc l'accusation \xC3\xA9tait garantie et non m\xC3\xA9rit\xC3\xA9""e. Elle est supprim\xC3\xA9""e, pas r\xC3\xA9gl\xC3\xA9""e -- une v\xC3\xA9rification qui se d\xC3\xA9""clenche \xC3\xA0 tort enterre celles qui ont raison. Tout fichier aiohud_bugreport date du 11 septembre est \xC3\xA0 jeter. Et le log ne qualifie plus d'\"unproven\" une adresse qui fonctionne.", CK_FIXED, "HUD", "HUD" },
    { "Under the hood, four watchers now run while you play and report into *//aio doctor* : a setting that cannot make up its mind and keeps flipping frame after frame, a fixed-size table that has run out of room (what does not fit is simply absent, in complete silence), the diagnoses the doctor could already give but only when asked, and a continuous record of the last decisions taken (*//aio why*). They only ever observe -- *//aio watch off* stops all of them at once.",
      "Dans les coulisses, quatre veilleurs tournent maintenant pendant que tu joues et rapportent dans *//aio doctor* : un r\xC3\xA9glage qui n'arrive pas \xC3\xA0 se d\xC3\xA9""cider et bascule image apr\xC3\xA8s image, une table de taille fixe qui d\xC3\xA9""borde (ce qui ne tient pas est simplement absent, sans un mot), les diagnostics que le doctor savait d\xC3\xA9j\xC3\xA0 donner mais seulement quand on les demandait, et un enregistrement continu des derni\xC3\xA8res d\xC3\xA9""cisions prises (*//aio why*). Ils ne font qu'observer -- *//aio watch off* les arr\xC3\xAAte tous d'un coup.", CK_NEW, "HUD", "HUD" },
};

static const ChangeLine CL_84[] = {
    { "*The menus work again after the game update.* A patch moved the client's data and the spell/ability cost box, along with the cursor that shows who you are selecting when you set a leader or a quartermaster, quietly stopped appearing. AioHUD finds those addresses by itself, but it had settled on the wrong one -- four bytes off, onto something that looks exactly like a menu and never is one. It now checks that what it found actually follows your cursor, and refuses anything that merely looks plausible.",
      "*Les menus refonctionnent apr\xC3\xA8s la mise \xC3\xA0 jour du jeu.* Un patch a d\xC3\xA9plac\xC3\xA9 les donn\xC3\xA9""es du client, et la bo\xC3\xAEte de co\xC3\xBBt des sorts et abilites, ainsi que le curseur qui montre qui tu s\xC3\xA9lectionn\xC3\xA9s pour passer leader ou quartermaster, ont cess\xC3\xA9 d'appara\xC3\xAEtre sans un mot. AioHUD retrouve ces adresses tout seul, mais il s'\xC3\xA9tait fix\xC3\xA9 sur la mauvaise -- quatre octets \xC3\xA0 c\xC3\xB4t\xC3\xA9, sur quelque chose qui ressemble \xC3\xA0 un menu sans jamais en \xC3\xAAtre un. Il v\xC3\xA9rifie d\xC3\xA9sormais que ce qu'il a trouv\xC3\xA9 suit r\xC3\xA9""ellement ton curseur, et refuse ce qui a seulement l'air plausible.", CK_FIXED, "Party", "Groupe" },
    { "*And it tells you when it is lost.* If a future update breaks the same thing, AioHUD writes a report naming the one action that repairs it -- open the Magic menu and move the cursor, and so on. No more feature that stops working without a word: the diagnosis was in the log all along, and nobody reads the log.",
      "*Et il te pr\xC3\xA9vient quand il est perdu.* Si une prochaine mise \xC3\xA0 jour casse la m\xC3\xAAme chose, AioHUD \xC3\xA9""crit un rapport qui nomme l'action unique qui r\xC3\xA9pare -- ouvrir le menu Magie et bouger le curseur, par exemple. Fini la fonction qui s'arr\xC3\xAAte sans rien dire : le diagnostic \xC3\xA9tait dans le log depuis le d\xC3\xA9""but, et personne ne lit le log.", CK_NEW, "HUD", "HUD" },
    { "*Songs sung under Tenuto or Clarion Call were shown 40 seconds short.* Both abilities add a flat bonus the duration model had stopped reading, since July. Checked against the game's own timer on seven casts: the durations are now exact to the second.",
      "*Les songs chant\xC3\xA9""es sous Tenuto ou Clarion Call \xC3\xA9taient affich\xC3\xA9""es 40 secondes trop courtes.* Les deux abilites ajoutent un bonus fixe que le mod\xC3\xA8le de dur\xC3\xA9""e ne lisait plus, depuis juillet. V\xC3\xA9rifi\xC3\xA9 contre le timer du jeu sur sept casts : les dur\xC3\xA9""es sont maintenant justes \xC3\xA0 la seconde.", CK_FIXED, "Timers", "Timers" },
    { "*The Timers box stops shaking when you replace your songs.* A song could be drawn as active and reported as lost in the same image, and the red line appeared and vanished thirty times a second. A replaced song no longer scatters into one line per member either, and a song you pushed out yourself to make room no longer raises an alert -- you did that on purpose.",
      "*La bo\xC3\xAEte Timers ne tremble plus quand tu remplaces tes songs.* Une song pouvait \xC3\xAAtre dessin\xC3\xA9""e comme active et signal\xC3\xA9""e comme perdue dans la m\xC3\xAAme image, et la ligne rouge apparaissait et disparaissait trente fois par seconde. Une song remplac\xC3\xA9""e ne s'\xC3\xA9parpille plus non plus en une ligne par membre, et une song que tu as pouss\xC3\xA9""e dehors toi-m\xC3\xAAme pour faire de la place ne d\xC3\xA9""clenche plus d'alerte -- tu l'as fait expr\xC3\xA8s.", CK_FIXED, "Timers", "Timers" },
    { "*Two songs on the same countdown stop trading places.* When two are within a second of each other, the order they already had is kept instead of being recomputed from a number that rounds differently every frame.",
      "*Deux songs sur le m\xC3\xAAme d\xC3\xA9""compte n'\xC3\xA9""changent plus leur place.* Quand elles sont \xC3\xA0 moins d'une seconde l'une de l'autre, l'ordre qu'elles avaient d\xC3\xA9j\xC3\xA0 est conserv\xC3\xA9 au lieu d'\xC3\xAAtre recalcul\xC3\xA9 depuis un nombre qui s'arrondit diff\xC3\xA9remment \xC3\xA0 chaque image.", CK_FIXED, "Timers", "Timers" },
    { "*Odyssey Sheol Gaol is no longer shown as Sheol A/B/C*, and the Abyssea visitant timer is read from your own status instead of a chat message whose number changes with every patch -- so it survives the next one.",
      "*Sheol Gaol dans Odyssey n'est plus affich\xC3\xA9 comme Sheol A/B/C*, et le timer de visitant en Abyssea est lu depuis ton propre statut au lieu d'un message de chat dont le num\xC3\xA9ro change \xC3\xA0 chaque patch -- il survivra donc au prochain.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
};

static const ChangeLine CL_83[] = {
    { "*The status icons that ship with AioHUD are the current set.* The sheet in the last version was an older revision of the same pack : 60 icons behind, among them all 31 Corsair rolls, drawn smaller than the rest, plus the Bar-spells, the stat boosts and penalties, Aquaveil and Phalanx. Nothing to do -- update and they are right.",
      "*Les ic\xC3\xB4nes de statut livr\xC3\xA9""es avec AioHUD sont celles \xC3\xA0 jour.* La planche de la version pr\xC3\xA9""c\xC3\xA9""dente \xC3\xA9tait une r\xC3\xA9vision plus ancienne du m\xC3\xAAme pack : 60 ic\xC3\xB4nes de retard, dont les 31 rolls de Corsaire, dessin\xC3\xA9s plus petits que le reste, plus les Bar-sorts, les boosts et malus de stats, Aquaveil et Phalanx. Rien \xC3\xA0 faire -- mets \xC3\xA0 jour et c'est correct.", CK_FIXED, "HUD", "HUD" },
    { "*Install an icon pack without XIPivot.* Drop it in *plugins\\AioHud\\icons\\packs\\<name>\\* -- the 57.DAT on its own, or the pack unzipped with its own ROM\\119 tree, or a sheet built with the icon application -- and it appears in the list under the name YOU gave the folder. That folder is never touched by an update or by a reinstall, unlike everything under assets.",
      "*Installer un pack d'ic\xC3\xB4nes sans XIPivot.* D\xC3\xA9pose-le dans *plugins\\AioHud\\icons\\packs\\<nom>\\* -- le 57.DAT seul, ou le pack d\xC3\xA9""compress\xC3\xA9 avec son arborescence ROM\\119, ou une planche construite avec l'application d'ic\xC3\xB4nes -- et il appara\xC3\xAEt dans la liste sous le nom que TU as donne au dossier. Ce dossier n'est jamais touch\xC3\xA9 par une mise \xC3\xA0 jour ni par une r\xC3\xA9installation, contrairement \xC3\xA0 tout ce qui est dans assets.", CK_NEW, "HUD", "HUD" },
    { "*The same pack is no longer listed three times.* The row offered every PLACE a sheet could be read from, so one pack installed as an XIPivot overlay and as your own sheet took three lines that all did the same thing. Sources that produce the same icons are now folded into one entry -- compared on the decoded image, not on the files, which is the only way a .raw and a .DAT holding the same art can be recognised as one. The name shown is the one that identifies the icons: a folder you named, then AioPack, then an XIPivot folder.",
      "*Le m\xC3\xAAme pack n'est plus liste trois fois.* La ligne proposait chaque ENDROIT d'o\xC3\xB9 une planche pouvait \xC3\xAAtre lue : un pack install\xC3\xA9 en overlay XIPivot et en feuille perso occupait trois lignes qui faisaient la m\xC3\xAAme chose. Les sources qui produisent les m\xC3\xAAmes ic\xC3\xB4nes sont d\xC3\xA9sormais r\xC3\xA9unies en une seule entr\xC3\xA9""e -- compar\xC3\xA9""es sur l'image d\xC3\xA9""cod\xC3\xA9""e, pas sur les fichiers, seule fa\xC3\xA7on de reconna\xC3\xAEtre qu'un .raw et un .DAT portent le m\xC3\xAAme dessin. Le nom affich\xC3\xA9 est celui qui identifie les ic\xC3\xB4nes : un dossier que tu as nomm\xC3\xA9, puis AioPack, puis un dossier XIPivot.", CK_FIXED, "HUD", "HUD" },
    { "*The application that installs your icons is on the release page.* AioHudIcons.exe takes a folder of PNGs or an icon DAT and writes the sheet the HUD reads, finding your AioHud folder by itself. One file, nothing to install, and the in-game updater never downloads it -- it is there for those who want it.",
      "*L'application qui installe tes ic\xC3\xB4nes est sur la page de release.* AioHudIcons.exe prend un dossier de PNG ou un DAT d'ic\xC3\xB4nes et \xC3\xA9""crit la planche que lit le HUD, en trouvant ton dossier AioHud tout seul. Un fichier, rien \xC3\xA0 installer, et l'updater in-game ne le t\xC3\xA9l\xC3\xA9""charge jamais -- il est l\xC3\xA0 pour qui en veut.", CK_NEW, "HUD", "HUD" },
};

static const ChangeLine CL_82[] = {
    { "*Choose which icon set the HUD draws.* Config > Interface > Status icons lists what is actually installed on your machine : Auto, the sheet AioHUD ships with, your own sheet if you built one, every XIPivot pack that carries the status icons, and the game's own art. Auto still decides for you and stays the default -- this line is there for the case it gets wrong, which is a group wanting the SAME icons rather than each their own installed pack. Pick a pack that later disappears and it quietly falls back to Auto rather than leaving you with no icons.",
      "*Choisis la planche d'ic\xC3\xB4nes que le HUD dessine.* Config > Interface > Ic\xC3\xB4nes de statut liste ce qui est r\xC3\xA9""ellement install\xC3\xA9 chez toi : Auto, la planche livr\xC3\xA9""e avec AioHUD, la tienne si tu en as fabriqu\xC3\xA9 une, chaque pack XIPivot qui contient les ic\xC3\xB4nes de statut, et l'art du jeu. Auto d\xC3\xA9""cide toujours pour toi et reste le d\xC3\xA9""faut -- cette ligne existe pour le cas o\xC3\xB9 il se trompe, c'est-\xC3\xA0-dire un groupe qui veut LES MEMES ic\xC3\xB4nes plut\xC3\xB4t que chacun le pack qu'il a install\xC3\xA9. Si le pack choisi dispara\xC3\xAEt un jour, on revient \xC3\xA0 Auto sans bruit plut\xC3\xB4t que de te laisser sans ic\xC3\xB4nes.", CK_NEW, "HUD", "HUD" },
    { "*An application to install your icons, on the release page.* AioHudIcons.exe takes a folder of PNGs or an icon DAT, shows you the result, and writes it where the HUD reads it -- it finds your AioHud folder by itself. One file, nothing to install. It is a separate download beside the zip : the in-game updater ignores it, so it costs nothing to those who do not want it.",
      "*Une application pour installer tes ic\xC3\xB4nes, sur la page de release.* AioHudIcons.exe prend un dossier de PNG ou un DAT d'ic\xC3\xB4nes, te montre le r\xC3\xA9sultat, et l'\xC3\xA9""crit l\xC3\xA0 o\xC3\xB9 le HUD le lit -- il trouve ton dossier AioHud tout seul. Un seul fichier, rien \xC3\xA0 installer. C'est un t\xC3\xA9l\xC3\xA9""chargement s\xC3\xA9par\xC3\xA9 \xC3\xA0 c\xC3\xB4t\xC3\xA9 du zip : l'updater in-game l'ignore, il ne co\xC3\xBBte donc rien \xC3\xA0 ceux qui n'en veulent pas.", CK_NEW, "HUD", "HUD" },
    { "*Dual-box : both characters come back from an update.* Updating from one client could leave the other one running the build it had BEFORE -- old icons, old code, with the update fully installed on disk -- or sitting unloaded until you typed //load by hand. Which of the two you got depended on the order two clients happened to poll in. Every client now reloads itself on its own, whatever that order is. One thing to do ONCE after this update : //lua reload aioupdate (or restart Windower), so it is the fixed addon that drives the NEXT update rather than the old one still in memory.",
      "*Dual-box : les deux personnages reviennent apr\xC3\xA8s une mise \xC3\xA0 jour.* Mettre \xC3\xA0 jour depuis un client pouvait laisser l'autre tourner sur la version d'AVANT -- anciennes ic\xC3\xB4nes, ancien code, avec la mise \xC3\xA0 jour pourtant install\xC3\xA9""e sur le disque -- ou reste d\xC3\xA9""charg\xC3\xA9 jusqu'\xC3\xA0 ce que tu tapes //load \xC3\xA0 la main. Lequel des deux d\xC3\xA9pendait de l'ordre dans lequel les deux clients avaient sonde. Chaque client se recharge maintenant tout seul, quel que soit cet ordre. Une chose \xC3\xA0 faire UNE fois apr\xC3\xA8s cette mise \xC3\xA0 jour : //lua reload aioupdate (ou relancer Windower), pour que ce soit l'addon corrig\xC3\xA9 qui pilote la PROCHAINE mise \xC3\xA0 jour et non l'ancien encore en m\xC3\xA9moire.", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
    { "*Job Badge stays in its column.* In Party rows, switching Job Badge to Off made Badge Size disappear beside it and the control stretch across the whole card -- so the row looked like it had jumped to the right on its own. It keeps its place now ; only its neighbour goes.",
      "*Le badge de job garde sa colonne.* Dans Lignes party, passer Badge de job sur Aucun faisait dispara\xC3\xAEtre Taille du badge \xC3\xA0 c\xC3\xB4t\xC3\xA9 et le contr\xC3\xB4le s'\xC3\xA9tirait sur toute la carte -- la ligne semblait donc partir \xC3\xA0 droite toute seule. Elle garde sa place ; seule sa voisine dispara\xC3\xAEt.", CK_FIXED, "Config", "Config" },
};

static const ChangeLine CL_81[] = {
    { "*A buff you re-cast shows up again.* Take a row off with */aio out*, then cast that buff again on someone who STILL has it -- Haste, Refresh and Regen overwrite themselves and never lapse -- and the row used to stay hidden for as long as you kept the buff up. A removed line is now tied to that ONE cast : a newer cast on that person brings it back, with its number and its real remaining time. A cast that does not land (no effect, resisted) leaves it off, since nothing changed on them.",
      "*Un buff relanc\xC3\xA9 se r\xC3\xA9""affiche.* Retire une ligne avec */aio out*, puis relance ce buff sur quelqu'un qui l'a TOUJOURS -- Haste, Refresh et Regen s'\xC3\xA9""crasent eux-m\xC3\xAAmes et ne tombent jamais -- et la ligne restait cach\xC3\xA9""e aussi longtemps que tu maintenais le buff. Une ligne retir\xC3\xA9""e ne vaut plus que pour CE cast-l\xC3\xA0 : un cast plus r\xC3\xA9""cent sur cette personne la ram\xC3\xA8ne, avec son num\xC3\xA9ro et son temps restant r\xC3\xA9""el. Un cast qui ne prend pas (sans effet, r\xC3\xA9sist\xC3\xA9) la laisse retir\xC3\xA9""e, puisque rien n'a chang\xC3\xA9 sur la cible.", CK_FIXED, "Timers", "Timers" },
    { "*Two new ways to tidy the Timers box.* */aio out alerts* takes off only the RED rows -- the buffs that have just run out -- and leaves every running timer alone ; */aio out all* still clears the lot. And */aio in* puts back everything you removed, or just the one you name (*/aio in 3*, */aio in gab*).",
      "*Deux nouvelles fa\xC3\xA7ons de ranger la bo\xC3\xAEte Timers.* */aio out alertes* ne retire que les lignes ROUGES -- les buffs qui viennent d'expirer -- et laisse tourner tous les minuteurs ; */aio out all* efface toujours tout. Et */aio in* remet ce que tu as retir\xC3\xA9, ou seulement la ligne que tu nommes (*/aio in 3*, */aio in gab*).", CK_NEW, "Timers", "Timers" },
    { "*Duration: show is finally obeyed.* A row about an ally forced icon + name whatever you had picked, while a grouped row followed the setting -- and a buff moves between those two forms as you re-cast, so the presentation changed on its own. The person is now held apart from the spell : *Icon* is icon + person, *Name* is person + spell, *Both* is all three. A row about someone else always names them.",
      "*Duration : afficher est enfin respect\xC3\xA9.* Une ligne qui concerne un alli\xC3\xA9 for\xC3\xA7""ait ic\xC3\xB4ne + nom quel que soit ton choix, alors qu'une ligne group\xC3\xA9""e, elle, suivait le r\xC3\xA9glage -- et un buff passe de l'une \xC3\xA0 l'autre au fil des recasts, donc la pr\xC3\xA9sentation changeait d'elle-m\xC3\xAAme. La personne est d\xC3\xA9sormais s\xC3\xA9par\xC3\xA9""e du sort : *Ic\xC3\xB4ne* donne ic\xC3\xB4ne + personne, *Nom* personne + sort, *Les deux* les trois. Une ligne qui concerne quelqu'un d'autre le nomme toujours.", CK_FIXED, "Timers", "Timers" },
    { "*Chat and console messages follow the language you picked.* Every line the plugin prints was a fixed mix of English and French : command feedback, the eleven diagnostic commands, */aio doctor* and its remedies, and the updater's own messages. They all follow the FR/EN switch in the config now -- one setting, not two.",
      "*Les messages du chat et de la console suivent la langue choisie.* Chaque ligne affich\xC3\xA9""e par le plugin \xC3\xA9tait un m\xC3\xA9lange fig\xC3\xA9 d'anglais et de fran\xC3\xA7""ais : retours de commandes, les onze commandes de diagnostic, */aio doctor* et ses rem\xC3\xA8""des, et les messages de l'updater. Tout suit d\xC3\xA9sormais le bouton FR/EN de la config -- un seul r\xC3\xA9glage, pas deux.", CK_IMPROVED, "HUD", "HUD" },
    { "*Status icons follow the icons you actually have.* If you run an icon pack -- XIPivot, or files copied over the game's own -- the HUD reads the game's icon sheet and shows exactly what your game shows, with nothing to set up. Without a pack it uses its bundled sheet, refreshed in this version. And *aioicons.ps1*, next to your AioHud data folder, extracts those icons as PNGs or installs a set of your own.",
      "*Les ic\xC3\xB4nes de statut suivent les ic\xC3\xB4nes que tu as vraiment.* Si tu utilises un pack d'ic\xC3\xB4nes -- XIPivot, ou des fichiers copi\xC3\xA9s par-dessus ceux du jeu -- le HUD lit la planche d'ic\xC3\xB4nes du jeu et affiche exactement ce que ton jeu affiche, sans rien \xC3\xA0 r\xC3\xA9gler. Sans pack, il utilise sa planche int\xC3\xA9gr\xC3\xA9""e, renouvel\xC3\xA9""e dans cette version. Et *aioicons.ps1*, \xC3\xA0 c\xC3\xB4t\xC3\xA9 de ton dossier de donn\xC3\xA9""es AioHud, extrait ces ic\xC3\xB4nes en PNG ou installe les tiennes.", CK_NEW, "HUD", "HUD" },
};

static const ChangeLine CL_89[] = {
    { "*Changing runes no longer fills the box with red OUT alerts.* A Rune Fencer swaps runes all the time, and the game drops the oldest one to make room -- every rune pushed out that way stayed as a permanent OUT. Now only the runes you placed LAST can alert : 2 with RUN as a support job, 3 as a main job. Each rune placed counts on its own, so two Ignis that run out show two alerts, and placing a new rune quiets the one it replaced.",
      "*Changer de rune ne remplit plus la bo\xC3\xAEte d'alertes OUT rouges.* Un Rune Fencer change de rune en permanence, et le jeu retire la plus ancienne pour faire de la place -- chaque rune \xC3\xA9ject\xC3\xA9""e ainsi restait en OUT pour toujours. Seules les runes pos\xC3\xA9""es EN DERNIER peuvent maintenant alerter : 2 avec RUN en job de soutien, 3 en job principal. Chaque rune pos\xC3\xA9""e compte \xC3\xA0 part, donc deux Ignis expir\xC3\xA9s donnent deux alertes, et poser une nouvelle rune fait taire celle qu'elle remplace.", CK_FIXED, "Timers", "Timers" },
    { "*//aio help and //aio report.* //aio help lists the commands. //aio report writes ONE file to send when something is wrong -- the doctor's findings and every internal check -- next to AioHud.dll ; send it with Windower\\plugins\\aiohud_debug.log.",
      "*//aio help et //aio report.* //aio help liste les commandes. //aio report \xC3\xA9""crit UN fichier \xC3\xA0 envoyer quand quelque chose ne va pas -- les constats du doctor et toutes les v\xC3\xA9rifications internes -- \xC3\xA0 c\xC3\xB4t\xC3\xA9 de AioHud.dll ; envoie-le avec Windower\\plugins\\aiohud_debug.log.", CK_NEW, "HUD", "HUD" },
    { "*//aio doctor checks the install itself.* It now tests that AioHUD can really write in its folder and in its log. On an install under Program Files that cannot, your settings, profiles and reports were lost at every reload without a word ; the doctor now says so, with the remedy. It also notes your Windower version, so two players can compare.",
      "*//aio doctor v\xC3\xA9rifie l'installation elle-m\xC3\xAAme.* Il teste maintenant qu'AioHUD peut vraiment \xC3\xA9""crire dans son dossier et dans son journal. Sur une installation sous Program Files qui ne le peut pas, tes r\xC3\xA9glages, profils et rapports \xC3\xA9taient perdus \xC3\xA0 chaque rechargement sans un mot ; le doctor le dit maintenant, avec le rem\xC3\xA8""de. Il note aussi ta version de Windower, pour que deux joueurs puissent comparer.", CK_NEW, "HUD", "HUD" },
    { "*The advice //aio doctor gives now works.* After an FFXI update it can tell you to run //aio rva -- that command only existed in development builds and answered \"unknown command\". It is available now, and so is //aio bcaptlog, which a log line also asked for.",
      "*Les conseils de //aio doctor fonctionnent.* Apr\xC3\xA8s une mise \xC3\xA0 jour de FFXI il peut te dire de lancer //aio rva -- cette commande n'existait que dans les versions de d\xC3\xA9veloppement et r\xC3\xA9pondait \"unknown command\". Elle est disponible, tout comme //aio bcaptlog, qu'une ligne du journal demandait aussi.", CK_FIXED, "HUD", "HUD" },
    { "*After an FFXI update, the Cost/Next box repairs itself again.* When the game moved its addresses, one of the two self-repairs overwrote the correct answer of the other, and the box could stay empty until the next update.",
      "*Apr\xC3\xA8s une mise \xC3\xA0 jour de FFXI, la bo\xC3\xAEte Co\xC3\xBBt/Next se r\xC3\xA9pare de nouveau toute seule.* Quand le jeu d\xC3\xA9pla\xC3\xA7""ait ses adresses, l'une des deux r\xC3\xA9parations automatiques \xC3\xA9""crasait la bonne r\xC3\xA9ponse de l'autre, et la bo\xC3\xAEte pouvait rester vide jusqu'\xC3\xA0 la mise \xC3\xA0 jour suivante.", CK_FIXED, "Party", "Groupe" },
    { "*//aio out and //aio in only do what they say.* A name containing another command's word -- \"Poppy\", \"Simon\" -- used to trigger that command instead : //aio out Poppy changed the EmpyPop NM you track.",
      "*//aio out et //aio in ne font que ce qu'ils disent.* Un nom contenant le mot d'une autre commande -- \"Poppy\", \"Simon\" -- d\xC3\xA9""clenchait cette commande \xC3\xA0 la place : //aio out Poppy changeait le NM suivi par EmpyPop.", CK_FIXED, "Timers", "Timers" },
    { "*Names from the 10 September update.* The 24 new items and the renamed monster abilities show their real names. Miracle Cheer keeps its +30 % song duration even though the game's own English description of it is now damaged.",
      "*Les noms de la mise \xC3\xA0 jour du 10 septembre.* Les 24 nouveaux objets et les comp\xC3\xA9tences de monstres renomm\xC3\xA9""es affichent leur vrai nom. Miracle Cheer garde ses +30 % de dur\xC3\xA9""e de chant, m\xC3\xAAme si la description anglaise du jeu est maintenant ab\xC3\xAEm\xC3\xA9""e.", CK_IMPROVED, "HUD", "HUD" },
    { "Privacy : //aio keylog (an input diagnostic) now stops by itself after 60 seconds, and never records what you type in the chat -- only keys typed inside the AioHUD settings.",
      "Confidentialit\xC3\xA9 : //aio keylog (un diagnostic du clavier) s'arr\xC3\xAAte maintenant tout seul apr\xC3\xA8s 60 secondes, et n'enregistre jamais ce que tu tapes dans le chat -- seulement les touches tap\xC3\xA9""es dans les r\xC3\xA9glages d'AioHUD.", CK_IMPROVED, "HUD", "HUD" },
    { "A few developer commands left the release : //aio hp / mp / tp (bar fill), //aio sim, //aio corners and //aio lay. //aio party N and the demo rows are unchanged. The diagnostic log is also much smaller.",
      "Quelques commandes de d\xC3\xA9veloppement quittent la version publique : //aio hp / mp / tp (remplissage des barres), //aio sim, //aio corners et //aio lay. //aio party N et les lignes de demo ne changent pas. Le journal de diagnostic est aussi bien plus l\xC3\xA9ger.", CK_IMPROVED, "HUD", "HUD" },
};

static const ChangeLine CL_88[] = {
    { "*Gear icons are right again after the 10 September game update.* The update enlarged every item record in the game's icon files, and the plugin kept reading them at the old size -- so an icon could be another item's, or missing (Quicksilver was the first report). Icons are read at the new size, and a wrong icon already saved on your machine repairs itself.",
      "*Les ic\xC3\xB4nes d'\xC3\xA9quipement sont de nouveau justes apr\xC3\xA8s la mise \xC3\xA0 jour du jeu du 10 septembre.* La mise \xC3\xA0 jour a agrandi chaque fiche d'objet dans les fichiers d'ic\xC3\xB4nes du jeu, et le plugin les lisait encore \xC3\xA0 l'ancienne taille -- une ic\xC3\xB4ne pouvait \xC3\xAAtre celle d'un autre objet, ou manquer (Quicksilver a \xC3\xA9t\xC3\xA9 le premier signalement). Les ic\xC3\xB4nes sont lues \xC3\xA0 la nouvelle taille, et une ic\xC3\xB4ne fausse d\xC3\xA9j\xC3\xA0 enregistr\xC3\xA9""e sur ta machine se r\xC3\xA9pare d'elle-m\xC3\xAAme.", CK_FIXED, "Player", "Joueur" },
    { "*The Treasure Pool box shows what is already in the pool.* Items that dropped before the plugin loaded -- after an update, a reload, or a missed packet -- stayed invisible until they expired. The box now takes them from the game's own pool, with their remaining time, the highest lot and who holds it.",
      "*La bo\xC3\xAEte Treasure Pool affiche ce qui est d\xC3\xA9j\xC3\xA0 dans le pool.* Les objets tomb\xC3\xA9s avant le chargement du plugin -- apr\xC3\xA8s une mise \xC3\xA0 jour, un rechargement ou un paquet manqu\xC3\xA9 -- restaient invisibles jusqu'\xC3\xA0 leur expiration. La bo\xC3\xAEte les reprend maintenant du pool du jeu lui-m\xC3\xAAme, avec leur temps restant, le meilleur lot et qui le d\xC3\xA9tient.", CK_FIXED, "Treasure Pool", "Tr\xC3\xA9sor" },
    { "*PointWatch keeps your Master Level when you change zone.* After every zone it fell back to Master Level 0 -- and switched to the experience row -- for as long as it took the game to send the value again, often minutes.",
      "*PointWatch garde ton Master Level quand tu changes de zone.* Apr\xC3\xA8s chaque zone il retombait \xC3\xA0 Master Level 0 -- et passait sur la ligne d'exp\xC3\xA9rience -- le temps que le jeu renvoie la valeur, souvent plusieurs minutes.", CK_FIXED, "PointWatch", "PointWatch" },
    { "*The fallback to your battle target is your party's real battle target.* When your cursor is not on a mob, the box looks at <bt>. What it read was in fact the last thing your cursor was on. It now works <bt> out the way the game does : the mob claimed by you or your party.",
      "*Le repli sur ta cible de combat est la vraie cible de combat du groupe.* Quand ton curseur n'est pas sur un monstre, la bo\xC3\xAEte regarde <bt>. Ce qu'elle lisait \xC3\xA9tait en fait la derni\xC3\xA8re chose sous ton curseur. <bt> est maintenant calcul\xC3\xA9 comme le fait le jeu : le monstre r\xC3\xA9""clam\xC3\xA9 par toi ou ton groupe.", CK_FIXED, "Skillchains", "Skillchains" },
    { "*Buff durations measured against the game, and corrected where they were wrong.* Composure on your own enhancing spells is now counted. An Indi- aura counts its \"Indi. eff. dur. +%\" gear. An Entrust stays recognised for its full minute instead of 15 seconds. And a buff someone else cast on you is no longer credited to you.",
      "*Dur\xC3\xA9""es de buffs mesur\xC3\xA9""es contre le jeu, et corrig\xC3\xA9""es l\xC3\xA0 o\xC3\xB9 elles \xC3\xA9taient fausses.* Composure sur tes propres sorts d'am\xC3\xA9lioration est maintenant pris en compte. Une aura Indi- compte l'\xC3\xA9quipement \"Indi. eff. dur. +%\". Un Entrust reste reconnu pendant toute sa minute au lieu de 15 secondes. Et un buff lanc\xC3\xA9 sur toi par quelqu'un d'autre ne t'est plus attribu\xC3\xA9.", CK_FIXED, "Timers", "Timers" },
    { "Stability : with more than 24 buffs watched in Timers (an RDM keeping five buffs on five allies), or many buffs on the party, two internal tables were written past their end every frame. Fixed.",
      "Stabilit\xC3\xA9 : avec plus de 24 buffs suivis dans Timers (un RDM qui garde cinq buffs sur cinq alli\xC3\xA9s), ou beaucoup de buffs sur le groupe, deux tables internes \xC3\xA9taient \xC3\xA9""crites au-del\xC3\xA0 de leur fin \xC3\xA0 chaque image. Corrig\xC3\xA9.", CK_FIXED, "Timers", "Timers" },
    { "//aio doctor now also reports a minimap that cannot load and gear icons that do not match the game's files, instead of only writing it to the log.",
      "//aio doctor signale aussi une minimap qui ne se charge pas et des ic\xC3\xB4nes d'\xC3\xA9quipement qui ne correspondent pas aux fichiers du jeu, au lieu de l'\xC3\xA9""crire seulement dans le journal.", CK_IMPROVED, "HUD", "HUD" },
    { "*Red OUT alerts keep the names of who lost the buff.* When several people lost a buff you had cast on them one by one -- Haste, Phalanx, Regen -- the alerts folded into a single nameless \"(AoE N)\" line. Only a real area cast (a song, Protectra, a spell under Accession) groups now ; everything else keeps one alert per person.",
      "*Les alertes OUT rouges gardent le nom de qui a perdu le buff.* Quand plusieurs personnes perdaient un buff que tu leur avais lanc\xC3\xA9 un par un -- Haste, Phalanx, Regen -- les alertes se repliaient en une seule ligne \"(AoE N)\" sans nom. Seul un vrai sort de zone (une chanson, Protectra, un sort sous Accession) se regroupe maintenant ; tout le reste garde une alerte par personne.", CK_FIXED, "Timers", "Timers" },
};

static const ChangeLine CL_103[] = {
    { "*The game could crash when GearSwap was unloaded or reloaded.* The updater (aioupdate) kept two background checks running in a way that Windower filed under GearSwap ; unloading GearSwap then damaged the game's memory. The updater now runs them once a second without that mechanism (aioupdate 2.7).",
      "*Le jeu pouvait planter quand GearSwap \xC3\xA9tait d\xC3\xA9""charg\xC3\xA9 ou recharge.* Le programme de mise \xC3\xA0 jour (aioupdate) gardait deux contr\xC3\xB4les en fond d'une fa\xC3\xA7on que Windower rangeait sous GearSwap ; d\xC3\xA9""charger GearSwap ab\xC3\xAEmait alors la m\xC3\xA9moire du jeu. Il les fait maintenant une fois par seconde sans ce m\xC3\xA9""canisme (aioupdate 2.7).", CK_FIXED, "Update", "Mise \xC3\xA0 jour" },
    { "*A shared recast shows the ability you used.* Some abilities share one recast -- Ecliptic Attrition and Lasting Emanation, the Phantom Rolls, the SP abilities. The line took the first name of its list : an Ecliptic Attrition read \"Lasting Emanation\". It now shows the one you last used.",
      "*Un recast partag\xC3\xA9 affiche la capacit\xC3\xA9 que tu as utilis\xC3\xA9""e.* Certaines capacit\xC3\xA9s partagent un recast -- Ecliptic Attrition et Lasting Emanation, les Phantom Rolls, les SP. La ligne prenait le premier nom de sa liste : un Ecliptic Attrition affichait \"Lasting Emanation\". Elle affiche maintenant celle que tu as utilis\xC3\xA9""e en dernier.", CK_FIXED, "Timers", "Timers" },
};
static const ChangeLine CL_102[] = {
    { "*No more bug report files every session.* Three checks wrote one each time you played : the Apollyon units message changed number with a game update (AioHud found it again, but only at the second payout of each run), the table of debuffs on mobs was too small for Limbus, where dozens of mobs get debuffed at once (32 -> 64), and a buff you keep up for hours by recasting it, like a COR's roll, was taken for an entry that is never cleaned up.",
      "*Plus de fichiers bug report \xC3\xA0 chaque session.* Trois contr\xC3\xB4les en \xC3\xA9""crivaient un \xC3\xA0 chaque fois que tu jouais : le message des units d'Apollyon a chang\xC3\xA9 de num\xC3\xA9ro avec une mise \xC3\xA0 jour du jeu (AioHud le retrouvait, mais seulement au deuxi\xC3\xA8me gain de chaque run), la table des debuffs sur les mobs \xC3\xA9tait trop petite pour Limbus, ou des dizaines de mobs sont d\xC3\xA9""buff\xC3\xA9s \xC3\xA0 la fois (32 -> 64), et un buff que tu gardes des heures en le relan\xC3\xA7""ant, comme un roll de COR, \xC3\xA9tait pris pour une entr\xC3\xA9""e jamais nettoy\xC3\xA9""e.", CK_FIXED, "HUD", "HUD" },
    { "*Limbus box : your units after an upgrade.* Units spent on an upgrade did not leave the box, which kept the total of the last coffer. Ask the Operator for your units (Apollyon or Temenos) : the box takes your balance and your cap from its answer at once. Temenos and Apollyon now each have their line with your cap (Temenos 62545/267000), remembered between sessions : the amount turns orange from 90 % and red at the cap, where units are lost.",
      "*Box Limbus : tes units apr\xC3\xA8s un upgrade.* Les units d\xC3\xA9pens\xC3\xA9""es pour un upgrade ne sortaient pas de la box, qui gardait le total du dernier coffre. Demande tes units \xC3\xA0 l'Operator (Apollyon ou Temenos) : la box prend aussit\xC3\xB4t ton solde et ton plafond dans sa r\xC3\xA9ponse. Temenos et Apollyon ont maintenant chacun leur ligne avec ton plafond (Temenos 62545/267000), gard\xC3\xA9 d'une session \xC3\xA0 l'autre : le chiffre passe en orange \xC3\xA0 partir de 90 % et en rouge au plafond, o\xC3\xB9 les units sont perdues.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
};
static const ChangeLine CL_101[] = {
    { "*//aio rva no longer freezes the game.* It searched the whole game memory in one go and could freeze it for tens of seconds. It now looks near the addresses it knew first (instant), and only if that finds nothing does it search the whole memory in the background, a little each frame (about 20 seconds, the game keeps running). //aio rva full searches everything, in the background too.",
      "*//aio rva ne fige plus le jeu.* Il fouillait toute la m\xC3\xA9moire du jeu d'un coup et pouvait le figer plusieurs dizaines de secondes. Il cherche maintenant d'abord pr\xC3\xA8s des adresses qu'il connaissait (instantan\xC3\xA9), et seulement si rien n'y est, il fouille toute la m\xC3\xA9moire en fond, un peu \xC3\xA0 chaque image (une vingtaine de secondes, le jeu continue). //aio rva full fouille tout, en fond aussi.", CK_FIXED, "HUD", "HUD" },
};
static const ChangeLine CL_100[] = {
    { "*The party selection cursor could stay off after a game update.* AioHud looks for it again by itself, but it can only prove it while you have something targeted, and it used to give up two minutes after loading. Loaded in a Mog House or in town with nothing targeted, the cursor stayed off for the whole session. It now keeps looking until you target someone : target a party member, or yourself, and the cursor comes back.",
      "*Le curseur de s\xC3\xA9lection de party pouvait rester \xC3\xA9teint apr\xC3\xA8s une mise \xC3\xA0 jour du jeu.* AioHud le recherche tout seul, mais il ne peut le prouver que pendant que tu as une cible, et il abandonnait deux minutes apr\xC3\xA8s le chargement. Charg\xC3\xA9 en Mog House ou en ville sans cible, le curseur restait \xC3\xA9teint toute la session. Il cherche maintenant jusqu'\xC3\xA0 ce que tu cibles quelqu'un : cible un membre de ta party, ou toi-m\xC3\xAAme, et le curseur revient.", CK_FIXED, "Party", "Groupe" },
};
static const ChangeLine CL_99[] = {
    { "*The Pet box for SMN (//aio config -> Pet -> SMN).* Your avatar or spirit in a disc, its HP as a ring and its TP as an inner arc, its name in its element's colour and its distance ; Blood Pact Rage and Ward and your SMN job abilities with their recast ; your MP ; and the pacts of that avatar you know, Rage then Ward, with their MP cost (red when you are short) and the skillchain a Rage opens. A spirit shows the spells it casts. The portrait goes on top of the box or beside it.",
      "*La bo\xC3\xAEte Pet pour SMN (//aio config -> Pet -> SMN).* Ton avatar ou ton esprit dans un disque, ses HP en anneau et son TP en arc int\xC3\xA9rieur, son nom \xC3\xA0 la couleur de son \xC3\xA9l\xC3\xA9ment et sa distance ; Blood Pact Rage et Ward et tes job abilities SMN avec leur recast ; tes MP ; et les pacts de cet avatar que tu connais, Rage puis Ward, avec leur co\xC3\xBBt en MP (en rouge s'il t'en manque) et la skillchain qu'ouvre un Rage. Un esprit montre les sorts qu'il lance. Le portrait se place au-dessus de la bo\xC3\xAEte ou \xC3\xA0 c\xC3\xB4t\xC3\xA9.", CK_NEW, "Pet", "Pet" },
    { "*The preview's avatar is yours to pick*, to check every one of the 14 avatars and 8 spirits before you summon it.",
      "*L'avatar de l'aper\xC3\xA7u se choisit*, pour v\xC3\xA9rifier chacun des 14 avatars et 8 esprits avant de l'invoquer.", CK_NEW, "Pet", "Pet" },
    { "*BST : your job abilities* (Reward, Call Beast, Spur, Killer Instinct, Unleash...) at the bottom of the box, with their recast, and *each Ready move's skillchain* in its own column between the move and its charges. Both can be turned off in the BST tab.",
      "*BST : tes job abilities* (Reward, Call Beast, Spur, Killer Instinct, Unleash...) en bas de la bo\xC3\xAEte, avec leur recast, et *la skillchain de chaque Ready move* dans sa propre colonne entre le move et ses charges. Les deux se coupent dans l'onglet BST.", CK_NEW, "Pet", "Pet" },
    { "A pet's TP is now in the violet of your own TP bar : blue is MP's colour everywhere else.",
      "Le TP d'un pet est maintenant du violet de ta propre barre de TP : le bleu est la couleur des MP partout ailleurs.", CK_IMPROVED, "Pet", "Pet" },
};
static const ChangeLine CL_98[] = {
    { "*The Magic and Ability cost boxes could stay empty after a game update.* After the FFXI update of November 10, 2026, AioHud looked for them again in the game's memory and took a counter that ticks on its own for the spell under your cursor, and the Ability box followed it. It now keeps only a value that changes when you move the cursor and then stays put, and it looks through many more places, nearest first. This version forgets the game addresses it had found and looks for them again : after updating, open Magic, then Abilities, and move the cursor over a few entries in each.",
      "*Les bo\xC3\xAEtes de co\xC3\xBBt Magie et Ability pouvaient rester vides apr\xC3\xA8s une mise \xC3\xA0 jour du jeu.* Apr\xC3\xA8s la mise \xC3\xA0 jour FFXI du 10 novembre 2026, AioHud les a recherch\xC3\xA9""es dans la m\xC3\xA9moire du jeu et a pris un compteur qui avance tout seul pour le sort sous ton curseur, et la bo\xC3\xAEte Ability l'a suivi. Il ne garde plus qu'une valeur qui change quand tu bouges le curseur puis reste fixe, et il cherche \xC3\xA0 beaucoup plus d'endroits, les plus proches d'abord. Cette version oublie les adresses du jeu qu'elle avait trouv\xC3\xA9""es et les recherche : apr\xC3\xA8s la mise \xC3\xA0 jour, ouvre Magie, puis Abilities, et passe le curseur sur quelques lignes dans chacun.", CK_FIXED, "Party", "Groupe" },
};
static const ChangeLine CL_97[] = {
    { "*//unload AioHud could close the game.* Since the PlayOnline update of November 2026, unloading AioHud (an update does it too) could crash the game a moment later, after a long session. AioHud now leaves the game window in a state that stays safe whatever else is hooked on it. The update TO this version still runs the old unload : close the game and extract the zip by hand, or update right after logging in.",
      "*//unload AioHud pouvait fermer le jeu.* Depuis la mise \xC3\xA0 jour PlayOnline de novembre 2026, d\xC3\xA9""charger AioHud (une mise \xC3\xA0 jour le fait aussi) pouvait faire planter le jeu un instant apr\xC3\xA8s, au bout d'une longue session. AioHud laisse maintenant la fen\xC3\xAAtre du jeu dans un \xC3\xA9tat s\xC3\xBBr, quoi qu'il y ait d'autre de branche dessus. La mise \xC3\xA0 jour VERS cette version passe encore par l'ancien unload : ferme le jeu et extrais le zip \xC3\xA0 la main, ou mets \xC3\xA0 jour juste apr\xC3\xA8s t'\xC3\xAAtre connect\xC3\xA9.", CK_FIXED, "HUD", "HUD" },
    { "*New Pet box, for BST and GEO (//aio config -> Pet).* One box, at one place, shows your pet ; what it holds follows your main job. Your BST box's place, size and frame carry over.",
      "*Nouvelle bo\xC3\xAEte Pet, pour BST et GEO (//aio config -> Pet).* Une seule bo\xC3\xAEte, \xC3\xA0 un seul endroit, montre ton pet ; son contenu suit ton job principal. La place, la taille et le cadre de ta bo\xC3\xAEte BST sont gard\xC3\xA9s.", CK_NEW, "Pet", "Pet" },
    { "*GEO : your luopan.* Its bubble tinted with its element, its HP as a ring with the %, its distance, your Indi- aura, Entrust, your MP and your job abilities (each icon fills back as its recast runs). A Cardinal Chant compass shows where your target stands and the bonus a -ra gets right now. Layouts : compass on top, side by side, or the bubble only.",
      "*GEO : ta luopan.* Sa bulle teint\xC3\xA9""e de son \xC3\xA9l\xC3\xA9ment, ses HP en anneau avec le %, sa distance, ton aura Indi-, Entrust, tes MP et tes job abilities (chaque ic\xC3\xB4ne se remplit pendant son recast). Une boussole Cardinal Chant montre o\xC3\xB9 est ta cible et le bonus qu'un -ra a en ce moment. Dispositions : boussole au-dessus, c\xC3\xB4te \xC3\xA0 c\xC3\xB4te, ou la bulle seule.", CK_NEW, "Pet", "Pet" },
    { "*BST : two more layouts.* Your pet on top in a disc (its picture, HP as a ring, TP as an inner arc, the three Ready charges below it) with its box underneath ; or your pet on top of its numbered moves only.",
      "*BST : deux dispositions de plus.* Ton pet en haut dans un disque (son image, ses HP en anneau, son TP en arc int\xC3\xA9rieur, les trois charges Ready dessous) avec sa bo\xC3\xAEte en dessous ; ou ton pet au-dessus de ses moves num\xC3\xA9rot\xC3\xA9s seulement.", CK_NEW, "Pet", "Pet" },
    { "*Skillchains with your pet's Ready moves.* Every Ready move now opens its skillchains (eight were missing, Fluid Spread among them). The \"Go!\" after a pet's move waits 4 s, as its window opens later than a weapon skill's (//aio scdelay to change it). Trusts in your party count too. A Blood Pact is offered on SMN only.",
      "*Skillchains avec les Ready moves de ton pet.* Chaque Ready move ouvre maintenant ses skillchains (il en manquait huit, dont Fluid Spread). Le \"Go!\" apr\xC3\xA8s le move d'un pet attend 4 s, car sa fen\xC3\xAAtre s'ouvre plus tard que celle d'un weapon skill (//aio scdelay pour le changer). Les Trusts de ton groupe comptent aussi. Un Blood Pact n'est propos\xC3\xA9 qu'en SMN.", CK_NEW, "Skillchains", "Skillchains" },
    { "BST : Sweet Caroline, Herald Henry and Brave Hero Glenn show their family and correlation.",
      "BST : Sweet Caroline, Herald Henry et Brave Hero Glenn montrent leur famille et leur corr\xC3\xA9lation.", CK_FIXED, "Pet", "Pet" },
};

static const ChangeLine CL_96[] = {
    { "*BST : a new layout built around Ready.* A dial on the left shows your three Ready charges : a full charge is lit, the one recharging fills like a clock, and the centre gives the seconds to the next one (MAX when all three are there). Your pet sits on its right, and its moves are listed below in smaller text.",
      "*BST : une nouvelle disposition construite autour de Ready.* Un cadran \xC3\xA0 gauche montre tes trois charges Ready : une charge pleine est allum\xC3\xA9""e, celle qui recharge se remplit comme une horloge, et le centre donne les secondes avant la prochaine (MAX quand les trois sont l\xC3\xA0). Ton pet est \xC3\xA0 sa droite, et ses moves sont listes dessous en plus petit.", CK_NEW, "Pet", "Pet" },
    { "Each move short of charges now shows how many seconds it still waits. The box uses warmer colours (amber, moss, bark) ; the text colours you set yourself are kept.",
      "Chaque move qui manque de charges montre maintenant combien de secondes il attend encore. La bo\xC3\xAEte prend des couleurs plus chaudes (ambre, mousse, \xC3\xA9""corce) ; les couleurs de texte que tu as r\xC3\xA9gl\xC3\xA9""es toi-m\xC3\xAAme sont gard\xC3\xA9""es.", CK_IMPROVED, "Pet", "Pet" },
    { "*BST : your pet's correlation.* Its family, the family it is strong against and the one it is weak to. In //aio config -> BST, Shows picks the pet's picture, its correlation, or both.",
      "*BST : la corr\xC3\xA9lation de ton pet.* Sa famille, celle contre qui il est fort et celle qui le bat. Dans //aio config -> BST, Affiche choisit l'image du pet, sa corr\xC3\xA9lation, ou les deux.", CK_NEW, "Pet", "Pet" },
};
static const ChangeLine CL_95[] = {
    { "*New BST module (//aio config -> BST).* Your pet's name, HP, TP and distance, your Ready charges with the time to the next one, and the Ready moves your pet has : each with its number (the N of a rdymove N macro), an icon for its kind (weapon, element, or the status it gives or inflicts) and its cost in charges. Every element can be switched on or off, and the box takes the same look options as the others.",
      "*Nouveau module BST (//aio config -> BST).* Le nom, les HP, le TP et la distance de ton pet, tes charges Ready avec le temps avant la prochaine, et les Ready moves de ton pet : chacun avec son num\xC3\xA9ro (le N d'une macro rdymove N), une ic\xC3\xB4ne pour son type (arme, \xC3\xA9l\xC3\xA9ment, ou le statut qu'il donne ou inflige) et son co\xC3\xBBt en charges. Chaque \xC3\xA9l\xC3\xA9ment s'active ou se coupe, et la bo\xC3\xAEte a les m\xC3\xAAmes options d'apparence que les autres.", CK_NEW, "Pet", "Pet" },
    { "The time a charge takes is measured on your own Ready moves (merits, job points and gear included) and remembered for each character. Until your first Ready move it is worked out from your merits and job points.",
      "La dur\xC3\xA9""e d'une charge est mesur\xC3\xA9""e sur tes propres Ready moves (merits, job points et gear compris) et gard\xC3\xA9""e pour chaque personnage. Avant ton premier Ready move, elle est calcul\xC3\xA9""e depuis tes merits et job points.", CK_NEW, "Pet", "Pet" },
    { "Placed against the bottom of the screen, the box stays against it whatever the number of moves of your pet. The preview in the settings shows every jug pet with its own moves. Pet pictures are not included yet : the box shows them once their files are added.",
      "Plac\xC3\xA9""e contre le bas de l'\xC3\xA9""cran, la bo\xC3\xAEte y reste quel que soit le nombre de moves de ton pet. L'aper\xC3\xA7u dans les r\xC3\xA9glages montre chaque jug pet avec ses propres moves. Les images des pets ne sont pas encore fournies : la bo\xC3\xAEte les affichera quand leurs fichiers seront ajout\xC3\xA9s.", CK_NEW, "Pet", "Pet" },
    { "*Sortie : the Auto Widescan track option now follows the character you play.* It was read from a file shared by every character of the install, so the track could keep running with the option shown Off. Your choice per character is respected.",
      "*Sortie : l'option Track Widescan auto suit maintenant le personnage que tu joues.* Elle \xC3\xA9tait lue dans un fichier partag\xC3\xA9 par tous les personnages de l'installation, donc le track pouvait continuer avec l'option affich\xC3\xA9""e Off. Ton choix par personnage est respect\xC3\xA9.", CK_FIXED, "Zone Tracker", "Zone Tracker" },
};
static const ChangeLine CL_94[] = {
    { "*The Merits row now follows your kills.* It only moved when you changed zone or opened the Status menu : between the two, each kill's limit points were counted and then put back to their old value. It now moves with every kill, and the number of merits takes the game's own total each time you earn one.",
      "*La ligne Merits suit maintenant tes kills.* Elle ne bougeait que quand tu changeais de zone ou ouvrais le menu Status : entre les deux, les limit points de chaque kill \xC3\xA9taient compt\xC3\xA9s puis remis \xC3\xA0 leur ancienne valeur. Elle avance maintenant \xC3\xA0 chaque kill, et le nombre de merits reprend le total du jeu \xC3\xA0 chaque merit gagn\xC3\xA9.", CK_FIXED, "PointWatch", "PointWatch" },
    { "Loaded in the middle of a zone, the limit points shown may be off until your next zone change or the Status menu ; the number of merits corrects itself at the next merit you earn.",
      "Charg\xC3\xA9 en pleine zone, le nombre de limit points affich\xC3\xA9 peut \xC3\xAAtre d\xC3\xA9""cal\xC3\xA9 jusqu'\xC3\xA0 ton prochain changement de zone ou l'ouverture du menu Status ; le nombre de merits se corrige au prochain merit gagn\xC3\xA9.", CK_IMPROVED, "PointWatch", "PointWatch" },
    { "*No more false bug reports after a long session.* The self test wrote a report saying a table was full when it was only holding old targets, sometimes while you stood idle in town. It now counts only what is really in use, and those tables are emptied when you change zone.",
      "*Plus de faux rapports de bug apr\xC3\xA8s une longue session.* L'auto-test \xC3\xA9""crivait un rapport disant qu'une table \xC3\xA9tait pleine alors qu'elle ne gardait que d'anciennes cibles, parfois quand tu \xC3\xA9tais \xC3\xA0 l'arr\xC3\xAAt en ville. Il ne compte plus que ce qui sert vraiment, et ces tables sont vid\xC3\xA9""es quand tu changes de zone.", CK_FIXED, "HUD", "HUD" },
};
static const ChangeLine CL_93[] = {
    { "*Sortie : the bitzer is found where it really is.* The basement bitzers move from one run to the next, and 1.0.92 used positions from a single earlier run, so the bitzer line pointed at the wrong place. Its position is now read from the game on every run ; until it is known the line shows a dash instead of a wrong distance. With *Auto Widescan track* ticked, the bitzer's position is also requested when you enter a basement wing (twice at most, and never once it is known).",
      "*Sortie : le bitzer est trouv\xC3\xA9 l\xC3\xA0 o\xC3\xB9 il est vraiment.* Les bitzers du sous-sol changent de place d'un run \xC3\xA0 l'autre, et la 1.0.92 utilisait les positions d'un seul run pr\xC3\xA9""c\xC3\xA9""dent, donc la ligne Bitzer pointait au mauvais endroit. Sa position est maintenant lue dans le jeu \xC3\xA0 chaque run ; tant qu'elle n'est pas connue, la ligne affiche un tiret au lieu d'une fausse distance. Avec *Track Widescan auto* coch\xC3\xA9, la position du bitzer est aussi demand\xC3\xA9""e en entrant dans une aile du sous-sol (deux fois au plus, et jamais une fois connue).", CK_FIXED, "Zone Tracker", "Zone Tracker" },
    { "*Sortie : the arrow now turns with you.* It pointed north-up like a map, so it only matched the screen when you faced north. It is now relative to where your character faces, like the game's radar : up = straight ahead, right = turn right. The compass letters (N, NE, SW...) still give the true direction.",
      "*Sortie : la fl\xC3\xA8""che tourne maintenant avec toi.* Elle pointait nord en haut comme une carte, donc elle ne correspondait \xC3\xA0 l'\xC3\xA9""cran que si tu regardais le nord. Elle est maintenant relative \xC3\xA0 la direction de ton personnage, comme le radar du jeu : en haut = droit devant, \xC3\xA0 droite = tourne \xC3\xA0 droite. Les lettres (N, NE, SO...) donnent toujours la vraie direction.", CK_IMPROVED, "Zone Tracker", "Zone Tracker" },
    { "*New command : //aio sortielog.* Type it at the start of a Sortie : for an hour, it writes to Windower\\plugins\\aiohud_debug.log each wing you arrive in, each NM and bitzer position, and every 5 s what the box shows. //aio sortielog off stops it. Send that file if the box ever disagrees with what you see.",
      "*Nouvelle commande : //aio sortielog.* Tape-la au d\xC3\xA9""but d'une Sortie : pendant une heure, elle \xC3\xA9""crit dans Windower\\plugins\\aiohud_debug.log chaque aile o\xC3\xB9 tu arriv\xC3\xA9s, chaque position de NM et de bitzer, et toutes les 5 s ce qu'affiche la bo\xC3\xAEte. //aio sortielog off l'arr\xC3\xAAte. Envoie ce fichier si la bo\xC3\xAEte ne correspond pas \xC3\xA0 ce que tu vois.", CK_NEW, "Zone Tracker", "Zone Tracker" },
    { "*After this update, type //lua reload aioupdate once* (in each client) : the bitzer request lives in the updater addon, and Windower keeps the old one in memory until it is reloaded.",
      "*Apr\xC3\xA8s cette mise \xC3\xA0 jour, tape //lua reload aioupdate une fois* (dans chaque client) : la demande de position du bitzer vit dans l'addon de mise \xC3\xA0 jour, et Windower garde l'ancien en m\xC3\xA9moire tant qu'il n'est pas recharge.", CK_IMPROVED, "Update", "Mise \xC3\xA0 jour" },
};
static const ChangeLine CL_92[] = {
    { "*New box : Absorb-TP.* Every Absorb-TP cast by your party or alliance, you included : the TP it drained in big (white, green, yellow, orange, red as it climbs ; blue when it drained nothing -- resisted or no effect), the time since, and how many that player landed. The line and its timer go from green to red as time passes, and the whole line turns red when that player has not cast one for too long (90 s by default, in its settings). Place it with //aio edit like the other boxes.",
      "*Nouvelle bo\xC3\xAEte : Absorb-TP.* Chaque Absorb-TP lanc\xC3\xA9 par ton groupe ou ton alliance, toi compris : les TP vol\xC3\xA9s en grand (blanc, vert, jaune, orange, rouge selon le montant ; bleu quand rien n'a \xC3\xA9t\xC3\xA9 vol\xC3\xA9 -- r\xC3\xA9sist\xC3\xA9 ou sans effet), le temps \xC3\xA9""coul\xC3\xA9, et combien ce joueur en a plac\xC3\xA9s. Le trait et le chrono passent du vert au rouge avec le temps, et la ligne enti\xC3\xA8re passe en rouge quand ce joueur n'en a plus lanc\xC3\xA9 depuis trop longtemps (90 s par d\xC3\xA9""faut, dans ses r\xC3\xA9glages). Elle se place avec //aio edit comme les autres bo\xC3\xAEtes.", CK_NEW, "Absorb-TP", "Absorb-TP" },
    { "*Sortie : the NM of the wing you are in, and its bitzer.* The Sortie box now rings the letter of the wing you stand in, and shows that wing's NM on its own line -- distance, an arrow pointing at it, the compass point, and DOWN once it is killed -- plus the bitzer in the basement wings. The NM's position comes from Widescan tracking : track it yourself, or tick *Auto Widescan track* in the Zone Tracker settings (off by default) and one track is started for you each time you enter a wing.",
      "*Sortie : le NM de l'aile o\xC3\xB9 tu es, et son bitzer.* La bo\xC3\xAEte Sortie entoure la lettre de l'aile o\xC3\xB9 tu te trouves, et affiche le NM de cette aile sur sa propre ligne -- distance, une fl\xC3\xA8""che qui pointe vers lui, la direction, et VAINCU une fois tu\xC3\xA9 -- plus le bitzer dans les ailes du sous-sol. La position du NM vient du suivi Widescan : lance-le toi-m\xC3\xAAme, ou coche *Track Widescan auto* dans les r\xC3\xA9glages du Zone Tracker (d\xC3\xA9sactiv\xC3\xA9 par d\xC3\xA9""faut) et un suivi est lanc\xC3\xA9 pour toi \xC3\xA0 chaque aile.", CK_NEW, "Zone Tracker", "Zone Tracker" },
    { "*After this update, type //lua reload aioupdate once* (in each client) : the Sortie option lives in the updater addon, and Windower keeps the old one in memory until it is reloaded.",
      "*Apr\xC3\xA8s cette mise \xC3\xA0 jour, tape //lua reload aioupdate une fois* (dans chaque client) : l'option Sortie vit dans l'addon de mise \xC3\xA0 jour, et Windower garde l'ancien en m\xC3\xA9moire tant qu'il n'est pas recharge.", CK_IMPROVED, "Update", "Mise \xC3\xA0 jour" },
    { "*A box can no longer grow off the screen.* A Treasure Pool filling up or a Skillchains box widening near an edge now slides back just enough to stay visible, and returns to its own place when it shrinks. Each box also has a new *Grows toward* setting (right / both sides / left) : changing it never moves the box, only the direction it will grow in. The defaults are the behaviour each box always had.",
      "*Une bo\xC3\xAEte ne peut plus d\xC3\xA9""border de l'\xC3\xA9""cran.* Un Treasure Pool qui se remplit ou une bo\xC3\xAEte Skillchains qui s'\xC3\xA9largit pr\xC3\xA8s d'un bord se d\xC3\xA9""cale juste ce qu'il faut pour rester visible, et revient \xC3\xA0 sa place quand elle r\xC3\xA9tr\xC3\xA9""cit. Chaque bo\xC3\xAEte a aussi un nouveau r\xC3\xA9glage *Grandit vers* (droite / des deux c\xC3\xB4t\xC3\xA9s / gauche) : le changer ne d\xC3\xA9place jamais la bo\xC3\xAEte, seulement le sens dans lequel elle grandira. Par d\xC3\xA9""faut, chaque bo\xC3\xAEte garde le comportement qu'elle a toujours eu.", CK_NEW, "HUD", "HUD" },
    { "*Nothing is dropped when you buff a full party.* The box held 50 lines, and a Red Mage buffing six people goes past that -- the lines cut were the buffs on your allies and, first of all, the red OUT lines that say someone lost one. It now holds 128.",
      "*Plus rien n'est perdu quand tu buffes un groupe complet.* La bo\xC3\xAEte tenait 50 lignes, et un Red Mage qui buffe six personnes d\xC3\xA9passe ce nombre -- les lignes coup\xC3\xA9""es \xC3\xA9taient les buffs sur tes alli\xC3\xA9s et, en premier, les lignes rouges OUT qui signalent qu'un buff est tomb\xC3\xA9. Elle en tient maintenant 128.", CK_FIXED, "Timers", "Timers" },
    { "*The small //aio out numbers are hidden by default.* //aio out still takes a name (//aio out Aeryn Haste), alerts, or a number from //aio out list. Turn *//aio out numbers* on in Timers > Alerts to see them on the lines again.",
      "*Les petits num\xC3\xA9ros //aio out sont masqu\xC3\xA9s par d\xC3\xA9""faut.* //aio out accepte toujours un nom (//aio out Aeryn Haste), alertes, ou un num\xC3\xA9ro donne par //aio out list. Active *Num\xC3\xA9ros //aio out* dans Timers > Alertes pour les revoir sur les lignes.", CK_IMPROVED, "Timers", "Timers" },
    { "*A re-cast no longer flashes a false red OUT.* In the half-second between your cast and the game's own timer list, the same buff could be counted twice and the older copy reported as lost.",
      "*Une relance n'affiche plus un faux OUT rouge.* Dans la demi-seconde entre ton cast et la liste de timers du jeu, le m\xC3\xAAme buff pouvait \xC3\xAAtre compt\xC3\xA9 deux fois et l'ancienne copie annonc\xC3\xA9""e comme perdue.", CK_FIXED, "Timers", "Timers" },
    { "Buffs on allies : *Leth. Chappel +2* now counts as a piece of the Composure set. A Red Mage wearing it was counted one piece short, and every buff they put on an ally read about 10% too short.",
      "Buffs sur alli\xC3\xA9s : la *Leth. Chappel +2* compte maintenant comme pi\xC3\xA8""ce du set Composure. Un Red Mage qui la portait \xC3\xA9tait compt\xC3\xA9 une pi\xC3\xA8""ce de moins, et chaque buff pos\xC3\xA9 sur un alli\xC3\xA9 paraissait environ 10 % trop court.", CK_FIXED, "Timers", "Timers" },
    { "*Gear icons no longer flicker back to item numbers.* The equipment viewer now keeps each icon for the whole session, so a gear swap mid-fight re-uses it instead of rebuilding it. And on setups that run the game through a graphics wrapper such as dgVoodoo, textures and game data the plugin wrongly rejected are now accepted.",
      "*Les ic\xC3\xB4nes d'\xC3\xA9quipement ne redeviennent plus des num\xC3\xA9ros d'objet.* L'afficheur d'\xC3\xA9quipement garde chaque ic\xC3\xB4ne toute la session, donc un changement d'\xC3\xA9quipement en combat la r\xC3\xA9utilise au lieu de la reconstruire. Et sur les installations qui passent par un wrapper graphique comme dgVoodoo, des textures et des donn\xC3\xA9""es du jeu que le plugin rejetait \xC3\xA0 tort sont maintenant accept\xC3\xA9""es.", CK_FIXED, "Player", "Joueur" },
    { "Config previews use made-up names only.",
      "Les aper\xC3\xA7us de la config n'utilisent plus que des noms invent\xC3\xA9s.", CK_IMPROVED, "Config", "Config" },
};
static const ChangeLine CL_91[] = {
    { "*The Scholar stratagem counter finally tells the truth.* The book's charge number and its countdown were built on a table copied from the old Lua addon. Two things were wrong with it. Every time the recharge bar crossed a whole charge -- right after you spend one, then once every 48 seconds while it refills -- the book showed ONE CHARGE LESS than you had for a full second, with the timer stuck at 0. And on a job subbing /SCH it did not look at your level at all : the charge count was decided in advance. It now comes from the Scholar level the game reports, MASTER LEVELS INCLUDED -- they raise your subjob's level, and the charges follow it (a level 58 subjob gets 3 charges every 80 seconds). AioHUD now takes the Scholar level from the game itself, Master Levels included, and MEASURES the recharge rate on your own character: using a stratagem tells the client exactly how long one charge takes, and that is the number the book uses -- so it is right whether or not you own the Job Point gift, at any level, and it will survive the day Square Enix changes it.",
      "*Le compteur de stratagems du Scholar dit enfin la v\xC3\xA9rit\xC3\xA9.* Le nombre de charges du livre et son d\xC3\xA9""compte reposaient sur une table recopi\xC3\xA9""e de l'ancien addon Lua. Elle se trompait deux fois. \xC3\x80 chaque fois que la recharge franchissait une charge enti\xC3\xA8re -- juste apr\xC3\xA8s en avoir d\xC3\xA9pens\xC3\xA9 une, puis toutes les 48 secondes pendant qu'elle se remplit -- le livre affichait UNE CHARGE DE MOINS pendant une seconde pleine, avec le timer bloqu\xC3\xA9 \xC3\xA0 0. Et sur un job en /SCH il ne regardait pas ton niveau du tout : le nombre de charges \xC3\xA9tait fix\xC3\xA9 d'avance. Il vient maintenant du niveau de Scholar que le jeu annonce, MASTER LEVELS COMPRIS -- ce sont eux qui font monter le niveau de ton subjob, et les charges suivent (un subjob niveau 58 a 3 charges toutes les 80 secondes). AioHUD lit maintenant le niveau de Scholar dans le jeu lui-m\xC3\xAAme, Master Levels compris, et MESURE la cadence sur ton propre personnage : utiliser un stratagem indique au client exactement la dur\xC3\xA9""e d'une charge, et c'est ce nombre que le livre utilise -- donc juste que tu aies le don de Job Points ou non, \xC3\xA0 n'importe quel niveau, et \xC3\xA7""a survivra au jour o\xC3\xB9 Square Enix la changera.", CK_FIXED, "Grimoire", "Grimoire" },
    { "*The Cost/Next box says something useful for a stratagem.* Every stratagem -- Accession, Penury, Addendum, Immanence... -- shares one recharge bar, and the game counts it down to the bar being FULL. So hovering one showed \"Next 2:30\" while three charges sat there ready to use. It now shows the wait for the NEXT charge, and how many you can spend right now.",
      "*La bo\xC3\xAEte Cost/Next dit enfin quelque chose d'utile pour un stratagem.* Tous les stratagems -- Accession, Penury, Addendum, Immanence... -- partagent une seule barre de recharge, et le jeu la d\xC3\xA9""compte jusqu'\xC3\xA0 ce qu'elle soit PLEINE. Survoler l'un d'eux affichait donc \"Next 2:30\" alors que trois charges \xC3\xA9taient disponibles. Elle affiche maintenant l'attente avant la PROCHAINE charge, et combien tu peux en d\xC3\xA9penser tout de suite.", CK_FIXED, "Party", "Groupe" },
};

static const ChangeLine CL_90[] = {
    { "*A buff re-cast at another tier no longer turns red.* Phalanx and Phalanx II are one and the same buff, and the game keeps only one of them -- so casting either over the other replaces it. The box treated the replaced one as LOST : Phalanx II on the party, then an Accession Phalanx, and every Phalanx II sat in a permanent red OUT while everyone plainly had Phalanx. It applies to any tier change : Haste to Haste II, Regen II to Regen III, Protect IV to Protect V.",
      "*Un buff relanc\xC3\xA9 \xC3\xA0 un autre palier ne passe plus en rouge.* Phalanx et Phalanx II sont un seul et m\xC3\xAAme buff, et le jeu n'en garde qu'un -- lancer l'un par-dessus l'autre le remplace. La bo\xC3\xAEte prenait le remplac\xC3\xA9 pour un buff PERDU : Phalanx II sur le groupe, puis un Phalanx en Accession, et tous les Phalanx II restaient en OUT rouge permanent alors que tout le monde avait bien Phalanx. Valable pour tout changement de palier : Haste vers Haste II, Regen II vers Regen III, Protect IV vers Protect V.", CK_FIXED, "Timers", "Timers" },
    { "*The cursor that follows the game's party menu comes back, for good.* When you open Menu > Party > Distribution to set a Quartermaster, change leader or start a lottery, AioHUD lights up the member the menu points at. That cursor could disappear and never return, even after a reload : the plugin re-finds the game's addresses by itself, and it had settled on a wrong one -- adopted from four bytes of data that merely changed, and then saved as proven, so every load restored it. It now requires what it reads to actually look like a menu name, and any wrong address already saved on your machine is discarded on this update.",
      "*Le curseur qui suit le menu de groupe du jeu revient, d\xC3\xA9""finitivement.* Quand tu ouvres Menu > Party > Distribution pour d\xC3\xA9signer un Quartermaster, changer de leader ou lancer une loterie, AioHUD allume le membre que le menu pointe. Ce curseur pouvait dispara\xC3\xAEtre et ne jamais revenir, m\xC3\xAAme apr\xC3\xA8s un rechargement : le plugin retrouve les adresses du jeu tout seul, et il s'\xC3\xA9tait fix\xC3\xA9 sur une mauvaise -- adopt\xC3\xA9""e \xC3\xA0 partir de quatre octets qui changeaient simplement, puis enregistr\xC3\xA9""e comme prouv\xC3\xA9""e, donc chaque chargement la restaurait. Il exige maintenant que ce qu'il lit ressemble vraiment \xC3\xA0 un nom de menu, et toute mauvaise adresse d\xC3\xA9j\xC3\xA0 enregistr\xC3\xA9""e sur ta machine est jet\xC3\xA9""e \xC3\xA0 cette mise \xC3\xA0 jour.", CK_FIXED, "Party", "Groupe" },
    { "Robustness : the Limbus floor and gauge were read from a packet four bytes past what the server declared. Nothing visibly wrong came of it, but the value could have been anything ; the limit is now the one the game's own code uses.",
      "Robustesse : l'\xC3\xA9tage et la jauge de Limbus \xC3\xA9taient lus quatre octets au-del\xC3\xA0 de ce que le serveur annonce. Rien de visible n'en d\xC3\xA9""coulait, mais la valeur pouvait \xC3\xAAtre n'importe quoi ; la limite est maintenant celle qu'utilise le code du jeu lui-m\xC3\xAAme.", CK_IMPROVED, "Zone Tracker", "Zone Tracker" },
};

